INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('6d11fe1d-a536-5b79-a985-1f2c754cc7e3', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 13, 13, 'I will take the cup of salvation, and call on the name of Yahweh.'),
  ('ec6d4e7c-8524-5e6b-aae3-52a15576457d', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 14, 14, 'I will pay my vows to Yahweh, yes, in the presence of all his people.'),
  ('434c0bd4-2c07-593c-af36-8d9c812a6b9f', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 15, 15, 'Precious in the sight of Yahweh is the death of his saints.'),
  ('078c675f-95dc-58e9-a129-784d3a1edccf', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 16, 16, 'Yahweh, truly I am your servant. I am your servant, the son of your handmaid. You have freed me from my chains.'),
  ('81f118d9-44a8-523a-ae88-23d4d2b58d8a', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 17, 17, 'I will offer to you the sacrifice of thanksgiving, and will call on the name of Yahweh.'),
  ('7a434b96-be8b-5344-ab58-aa2d45c0866a', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 18, 18, 'I will pay my vows to Yahweh, yes, in the presence of all his people,'),
  ('544775e5-c6b1-5aae-a217-b9f256c08dae', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 19, 19, 'in the courts of Yahweh''s house, in the midst of you, Jerusalem. Praise Yah!'),
  ('95e713e0-5f0f-5bd0-ab35-1c7e085b5951', '50fe6344-90c0-59c3-a661-dd4e361f8219', NULL, 1, 1, 'Praise Yahweh, all you nations! Extol him, all you peoples!'),
  ('996c7dab-3bdc-59c5-a58e-11096c56a495', '50fe6344-90c0-59c3-a661-dd4e361f8219', NULL, 2, 2, 'For his loving kindness is great toward us. Yahweh''s faithfulness endures forever. Praise Yah!'),
  ('4aa3a14f-83b0-5ab9-a77f-6a5aaac6eb34', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 1, 1, 'Give thanks to Yahweh, for he is good, for his loving kindness endures forever.'),
  ('4fb75d04-17fb-5366-a464-48fe790a8229', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 2, 2, 'Let Israel now say that his loving kindness endures forever.'),
  ('441079f5-5d15-57aa-af53-f5083174fd72', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 3, 3, 'Let the house of Aaron now say that his loving kindness endures forever.'),
  ('af2d1094-1c44-577b-aeac-8e898cb13b6b', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 4, 4, 'Now let those who fear Yahweh say that his loving kindness endures forever.'),
  ('0c1f7d2d-8b50-59e4-afa0-53efedad0dab', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 5, 5, 'Out of my distress, I called on Yah. Yah answered me with freedom.'),
  ('e3a028db-cff1-575c-a5cd-f2c07133a7be', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 6, 6, 'Yahweh is on my side. I will not be afraid. What can man do to me?'),
  ('f4785e5d-7f26-5415-a337-9f82f8191e17', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 7, 7, 'Yahweh is on my side among those who help me. Therefore I will look in triumph at those who hate me.'),
  ('acceed08-1146-56d1-a9a9-4df29cbca9d0', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 8, 8, 'It is better to take refuge in Yahweh, than to put confidence in man.'),
  ('20ce124e-3e39-50bf-aa5e-61c292a3c1a2', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 9, 9, 'It is better to take refuge in Yahweh, than to put confidence in princes.'),
  ('3f45c16a-e82a-56a1-a739-5fb3b19904d5', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 10, 10, 'All the nations surrounded me, but in the name of Yahweh, I cut them off.'),
  ('ac89c180-e5e2-5776-a88e-42ee0d9b5536', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 11, 11, 'They surrounded me, yes, they surrounded me. In the name of Yahweh I indeed cut them off.'),
  ('77959409-24a6-564c-a49f-5c093e75740d', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 12, 12, 'They surrounded me like bees. They are quenched like the burning thorns. In the name of Yahweh I cut them off.'),
  ('0c6f3fc0-e4e4-5e7a-a021-f899340d95d0', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 13, 13, 'You pushed me back hard, to make me fall, but Yahweh helped me.'),
  ('17193385-c66a-5b79-a2b4-05ac0cd6fbc5', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 14, 14, 'Yah is my strength and song. He has become my salvation.'),
  ('4e42efc6-f5c5-5f0b-ae64-16a1e57d2999', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 15, 15, 'The voice of rejoicing and salvation is in the tents of the righteous. "The right hand of Yahweh does valiantly.'),
  ('89096e5a-c084-55b2-a4f8-f4cf637c0a68', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 16, 16, 'The right hand of Yahweh is exalted! The right hand of Yahweh does valiantly!"'),
  ('062c50f2-30c1-5174-a1a5-913297c34f8c', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 17, 17, 'I will not die, but live, and declare Yah''s works.'),
  ('0f47b0e8-cbbe-5fbd-a215-475c6884cb05', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 18, 18, 'Yah has punished me severely, but he has not given me over to death.'),
  ('fb374ede-d90b-545e-aa58-8cf6c47acb2a', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 19, 19, 'Open to me the gates of righteousness. I will enter into them. I will give thanks to Yah.'),
  ('9cb1f9c2-e846-560d-a49e-20e8c1d6d2bd', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 20, 20, 'This is the gate of Yahweh; the righteous will enter into it.'),
  ('524c5c56-6f0b-5ee3-aab5-1f8ec7c185e5', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 21, 21, 'I will give thanks to you, for you have answered me, and have become my salvation.'),
  ('7da8ad19-6491-555b-a44c-f5680ee3494e', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 22, 22, 'The stone which the builders rejected has become the head of the corner.'),
  ('e157108a-3aa8-545f-af25-12a9ba922879', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 23, 23, 'This is Yahweh''s doing. It is marvelous in our eyes.'),
  ('d273af79-4cf0-5ba0-a754-3b5881310f74', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 24, 24, 'This is the day that Yahweh has made. We will rejoice and be glad in it!'),
  ('e3f224de-588d-5af0-a2ae-adc9573bdf25', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 25, 25, 'Save us now, we beg you, Yahweh! Yahweh, we beg you, send prosperity now.'),
  ('bdf9f7ae-07f6-5958-a05a-4a3ee9e0f685', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 26, 26, 'Blessed is he who comes in the name of Yahweh! We have blessed you out of the house of Yahweh.'),
  ('1c235642-91fa-58ca-ae0e-79ca0b4f9c1b', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 27, 27, 'Yahweh is God, and he has given us light. Bind the sacrifice with cords, even to the horns of the altar.'),
  ('b5a35356-0f44-5ccc-ad08-9f700a9039b6', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 28, 28, 'You are my God, and I will give thanks to you. You are my God, I will exalt you.'),
  ('9e3b3f12-0ca2-5101-a647-c07f383ed3d8', '9ec4ef11-c9e5-577e-ac80-65f1227c7da0', NULL, 29, 29, 'Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever. ALEPH'),
  ('92d1dac4-e00a-5b04-aaba-fd23128cab25', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 1, 1, 'Blessed are those whose ways are blameless, who walk according to Yahweh''s law.'),
  ('4b000ffe-0ec6-5add-af41-abf279106c97', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 2, 2, 'Blessed are those who keep his statutes, who seek him with their whole heart.'),
  ('656b31c0-6938-5ba5-a95c-a1f60fbb2a6a', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 3, 3, 'Yes, they do nothing wrong. They walk in his ways.'),
  ('d75789af-a789-537c-a680-df36d5078eb0', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 4, 4, 'You have commanded your precepts, that we should fully obey them.'),
  ('ceb10082-2377-5c3d-aec2-94fe19e98777', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 5, 5, 'Oh that my ways were steadfast to obey your statutes!'),
  ('7d8e66e5-6b72-526c-ae3c-ae119f321a72', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 6, 6, 'Then I wouldn''t be disappointed, when I consider all of your commandments.'),
  ('f50f4e25-82d6-557e-a49e-5646fdd28cff', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 7, 7, 'I will give thanks to you with uprightness of heart, when I learn your righteous judgments.'),
  ('65db0ca0-f66c-5628-a102-f7159aea0db4', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 8, 8, 'I will observe your statutes. Don''t utterly forsake me. BET'),
  ('e12e030b-3815-59d7-a5bc-0784d661bfb8', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 9, 9, 'How can a young man keep his way pure? By living according to your word.'),
  ('d9b68794-dea3-51ee-a986-76698fe23257', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 10, 10, 'With my whole heart, I have sought you. Don''t let me wander from your commandments.'),
  ('ccc0224d-48f6-5cc6-a0ec-fc0545d54955', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 11, 11, 'I have hidden your word in my heart, that I might not sin against you.'),
  ('de299bc1-b574-5989-acb8-47de45d1572a', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 12, 12, 'Blessed are you, Yahweh. Teach me your statutes.'),
  ('aabb5b5d-e42c-594c-ab5b-2850325c5f9b', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 13, 13, 'With my lips, I have declared all the ordinances of your mouth.'),
  ('623118ee-93db-5ef1-a2fd-bbfbae0442e2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 14, 14, 'I have rejoiced in the way of your testimonies, as much as in all riches.'),
  ('638070e7-6db9-57f8-a2a0-6efe910a64ae', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 15, 15, 'I will meditate on your precepts, and consider your ways.'),
  ('6316ed3e-4f52-5770-a7dd-b499d0177b3f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 16, 16, 'I will delight myself in your statutes. I will not forget your word. GIMEL'),
  ('b0ebac56-002a-51d8-a75d-0420bcf757ec', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 17, 17, 'Do good to your servant. I will live and I will obey your word.'),
  ('d57b2e83-7468-52d7-a2ec-5b6ce734b32f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 18, 18, 'Open my eyes, that I may see wondrous things out of your law.'),
  ('2be585d1-0a32-585d-a98f-e5d021c05049', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 19, 19, 'I am a stranger on the earth. Don''t hide your commandments from me.'),
  ('1c0f2c74-601f-54da-a2a9-b6dc3c023c1f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 20, 20, 'My soul is consumed with longing for your ordinances at all times.'),
  ('05044a63-0048-598a-a07d-3740c56553df', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 21, 21, 'You have rebuked the proud who are cursed, who wander from your commandments.'),
  ('2a493a6a-3049-5aab-abe4-a7753d919d1d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 22, 22, 'Take reproach and contempt away from me, for I have kept your statutes.'),
  ('ae81f606-3af8-54e3-ac32-b368aeb85427', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 23, 23, 'Though princes sit and slander me, your servant will meditate on your statutes.'),
  ('af7427a8-c6ca-5826-aaaa-85fe1e6c679b', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 24, 24, 'Indeed your statutes are my delight, and my counselors. DALED'),
  ('ab4e1c64-3f47-58d2-aa4e-512f483be3f2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 25, 25, 'My soul is laid low in the dust. Revive me according to your word!'),
  ('17026614-0b63-5db9-ac43-ffd0a4c68f9d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 26, 26, 'I declared my ways, and you answered me. Teach me your statutes.'),
  ('b2ad4f6f-d257-5290-a2e7-348fc91037f8', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 27, 27, 'Let me understand the teaching of your precepts! Then I will meditate on your wondrous works.'),
  ('58d3000f-6b9d-5f0c-a670-e787a6472490', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 28, 28, 'My soul is weary with sorrow: strengthen me according to your word.'),
  ('97aef44b-c25c-5bcf-a64c-62c1670fa377', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 29, 29, 'Keep me from the way of deceit. Grant me your law graciously!'),
  ('844670f3-9170-5149-ac96-86c022c1069c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 30, 30, 'I have chosen the way of truth. I have set your ordinances before me.'),
  ('a9e91083-37f6-5936-a590-ada8ca905bb0', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 31, 31, 'I cling to your statutes, Yahweh. Don''t let me be disappointed.'),
  ('9d7159dc-d7b4-59eb-a1b2-935fc7d0cea5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 32, 32, 'I run in the path of your commandments, for you have set my heart free. HEY'),
  ('f704e46e-d94b-50ed-aae3-bfd7f271f00c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 33, 33, 'Teach me, Yahweh, the way of your statutes. I will keep them to the end.'),
  ('df2f7096-4f64-5f71-a795-b47dbae2288f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 34, 34, 'Give me understanding, and I will keep your law. Yes, I will obey it with my whole heart.'),
  ('0dfc288d-2cc9-55cb-ab12-d15988349f23', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 35, 35, 'Direct me in the path of your commandments, for I delight in them.'),
  ('f93e2f4c-5db0-52cf-a577-edc640f15ef7', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 36, 36, 'Turn my heart toward your statutes, not toward selfish gain.'),
  ('724fe61c-7bd8-50ae-a609-ca774a54459a', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 37, 37, 'Turn my eyes away from looking at worthless things. Revive me in your ways.'),
  ('3c75d390-7d80-5c58-a6f5-7836c32266bd', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 38, 38, 'Fulfill your promise to your servant, that you may be feared.'),
  ('acb8452b-0f6e-5d26-aa90-319184d6bbd9', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 39, 39, 'Take away my disgrace that I dread, for your ordinances are good.'),
  ('a3727fa1-505d-517b-acd2-12c75b6d1e81', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 40, 40, 'Behold, I long for your precepts! Revive me in your righteousness. WAW'),
  ('0b5e87c6-b596-5a76-a783-c6a5c57bb3f5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 41, 41, 'Let your loving kindness also come to me, Yahweh, your salvation, according to your word.'),
  ('6a0ab41c-db0a-5a75-a86f-8f863d5c825f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 42, 42, 'So I will have an answer for him who reproaches me, for I trust in your word.'),
  ('72c5fff8-a89b-5d7d-ab1f-4860e6b10656', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 43, 43, 'Don''t snatch the word of truth out of my mouth, for I put my hope in your ordinances.'),
  ('9f746920-2997-56bf-a8a1-ac1d711b4eda', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 44, 44, 'So I will obey your law continually, forever and ever.'),
  ('f40c8fd5-2cbf-5208-a13d-1d047c960be4', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 45, 45, 'I will walk in liberty, for I have sought your precepts.'),
  ('b16a3c77-9f9f-5410-af1e-cecd41c19eda', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 46, 46, 'I will also speak of your statutes before kings, and will not be disappointed.'),
  ('20ea2172-7cd1-5b8d-acb9-8bbd80a58cc8', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 47, 47, 'I will delight myself in your commandments, because I love them.'),
  ('cbe45a5a-7a18-5152-ae45-425fb7194564', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 48, 48, 'I reach out my hands for your commandments, which I love. I will meditate on your statutes. ZAYIN'),
  ('7b10f89d-b921-5c04-a35a-a4ee4a8f71a1', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 49, 49, 'Remember your word to your servant, because you gave me hope.'),
  ('3c5590e9-ea77-59e9-a6dc-8fc34c2e9372', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 50, 50, 'This is my comfort in my affliction, for your word has revived me.'),
  ('82a57ded-5619-5312-a350-4c1225a7f25e', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 51, 51, 'The arrogant mock me excessively, but I don''t swerve from your law.'),
  ('93e06ea0-5a17-5c92-a949-eac2209fd55e', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 52, 52, 'I remember your ordinances of old, Yahweh, and have comforted myself.'),
  ('fb53e950-e715-5caf-afb6-c59f6a6f02f1', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 53, 53, 'Indignation has taken hold on me, because of the wicked who forsake your law.'),
  ('63659379-098b-5492-ac69-60efffd14f6c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 54, 54, 'Your statutes have been my songs, in the house where I live.'),
  ('e5f8036f-30c8-56e8-aedd-24b80f7e79c5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 55, 55, 'I have remembered your name, Yahweh, in the night, and I obey your law.'),
  ('ec4238d6-24e6-561a-a054-419ab80ef7a5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 56, 56, 'This is my way, that I keep your precepts. CHET'),
  ('6590d8a1-daa9-584a-a47e-5ad9e942fedd', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 57, 57, 'Yahweh is my portion. I promised to obey your words.'),
  ('05360a7b-b119-5963-aca2-7a9894a30384', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 58, 58, 'I sought your favor with my whole heart. Be merciful to me according to your word.'),
  ('cf291aae-a74a-53c6-a503-bf2d2e2f9f16', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 59, 59, 'I considered my ways, and turned my steps to your statutes.'),
  ('ab9839b2-038c-5998-aa03-66ce82643f90', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 60, 60, 'I will hurry, and not delay, to obey your commandments.'),
  ('e4f448c5-ef26-5873-a90b-c59a6919016d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 61, 61, 'The ropes of the wicked bind me, but I won''t forget your law.'),
  ('57dcf536-b330-5821-a978-66be2e94d5c3', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 62, 62, 'At midnight I will rise to give thanks to you, because of your righteous ordinances.'),
  ('1c3640ec-6eca-5f81-af45-2646992f19cd', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 63, 63, 'I am a friend of all those who fear you, of those who observe your precepts.'),
  ('9090ba08-fa43-506a-ad83-9ff0d6ed4fe9', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 64, 64, 'The earth is full of your loving kindness, Yahweh. Teach me your statutes. TET'),
  ('7f3dffe7-4cc3-5866-ad1e-2f421eab77ce', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 65, 65, 'Do good to your servant, according to your word, Yahweh.'),
  ('563f64c5-9267-5eb1-aedb-8d7c4efed500', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 66, 66, 'Teach me good judgment and knowledge, for I believe in your commandments.'),
  ('52c3513a-6138-5da6-a6c0-c1b8f159c23c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 67, 67, 'Before I was afflicted, I went astray; but now I observe your word.'),
  ('7ebfc33c-5a47-5180-a6cf-eb37212fa8d5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 68, 68, 'You are good, and do good. Teach me your statutes.'),
  ('672402fd-6325-52ef-af35-8b1d337ab973', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 69, 69, 'The proud have smeared a lie upon me. With my whole heart, I will keep your precepts.'),
  ('b20ba884-991c-54e7-ada1-65454326350f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 70, 70, 'Their heart is as callous as the fat, but I delight in your law.'),
  ('08a0b34a-d8df-5e8e-a6e8-0e0bce439590', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 71, 71, 'It is good for me that I have been afflicted, that I may learn your statutes.'),
  ('23f3b9fe-8dc4-55a4-a122-05e8e10acde5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 72, 72, 'The law of your mouth is better to me than thousands of pieces of gold and silver. YUD'),
  ('7bf0133a-e126-5482-a100-709dffb1fd03', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 73, 73, 'Your hands have made me and formed me. Give me understanding, that I may learn your commandments.'),
  ('1b715a17-fd78-5ae1-a9ac-40846daa5062', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 74, 74, 'Those who fear you will see me and be glad, because I have put my hope in your word.'),
  ('1097ca8b-b183-593a-a362-c7f026c4d134', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 75, 75, 'Yahweh, I know that your judgments are righteous, that in faithfulness you have afflicted me.'),
  ('7e594a6a-fcd4-56f6-a25c-070d62a3ec06', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 76, 76, 'Please let your loving kindness be for my comfort, according to your word to your servant.'),
  ('8fa5f2fd-c051-56a1-ad56-a3912c7f6029', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 77, 77, 'Let your tender mercies come to me, that I may live; for your law is my delight.'),
  ('f474fef5-cbe1-50fa-a26f-cd3ebe7bb2ac', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 78, 78, 'Let the proud be disappointed, for they have overthrown me wrongfully. I will meditate on your precepts.'),
  ('ea5ed947-6c11-59af-afe1-0b027233a7c3', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 79, 79, 'Let those who fear you turn to me. They will know your statutes.'),
  ('98963626-da0f-563b-a722-78139f80f1ce', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 80, 80, 'Let my heart be blameless toward your decrees, that I may not be disappointed. KAF'),
  ('0c018bd4-2e14-5803-a294-ed7d6174acaa', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 81, 81, 'My soul faints for your salvation. I hope in your word.'),
  ('bf74a6b3-332e-5b12-aca6-a6d2b01c0d8b', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 82, 82, 'My eyes fail for your word. I say, "When will you comfort me?"'),
  ('dee5a6f3-50f4-5550-aecd-406119eb9abf', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 83, 83, 'For I have become like a wineskin in the smoke. I don''t forget your statutes.'),
  ('775084c0-4b26-5adc-a7c0-6067ddf39fdf', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 84, 84, 'How many are the days of your servant? When will you execute judgment on those who persecute me?'),
  ('54f00e6b-84a5-500d-aa76-b9452f0d5e5d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 85, 85, 'The proud have dug pits for me, contrary to your law.'),
  ('d5f8ec8f-1af7-534b-a6dd-881a5bb07aa3', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 86, 86, 'All of your commandments are faithful. They persecute me wrongfully. Help me!'),
  ('fe1d5c67-ea22-58e7-a068-bcf1a6ea33dc', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 87, 87, 'They had almost wiped me from the earth, but I didn''t forsake your precepts.'),
  ('5f6f2251-1578-5695-a856-c5089eb556e0', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 88, 88, 'Preserve my life according to your loving kindness, so I will obey the statutes of your mouth. LAMED'),
  ('a16b00c5-7e6d-59c6-a678-58ed2331acd7', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 89, 89, 'Yahweh, your word is settled in heaven forever.'),
  ('1e845afc-2cf9-5a6f-ae77-8b334540a9fa', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 90, 90, 'Your faithfulness is to all generations. You have established the earth, and it remains.'),
  ('d438589a-e838-5f9a-ac52-c10c012c7e5c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 91, 91, 'Your laws remain to this day, for all things serve you.'),
  ('7100ec3b-2f2f-5e1c-a69a-10c63973bd09', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 92, 92, 'Unless your law had been my delight, I would have perished in my affliction.'),
  ('7d2d24a4-8f11-578b-a8b1-7aa0b456f563', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 93, 93, 'I will never forget your precepts, for with them, you have revived me.'),
  ('b34ad1f9-7af4-53d7-adf7-7ba2b5af7be7', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 94, 94, 'I am yours. Save me, for I have sought your precepts.'),
  ('a34ca690-2993-5dab-a989-072ed6fb4b5d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 95, 95, 'The wicked have waited for me, to destroy me. I will consider your statutes.'),
  ('b8a280d6-2ad9-5306-af8b-ef86a2d51f95', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 96, 96, 'I have seen a limit to all perfection, but your commands are boundless. MEM'),
  ('44751d09-ceb0-526c-a86b-96a7fbe387b4', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 97, 97, 'How I love your law! It is my meditation all day.'),
  ('6164e307-9f5e-5d9f-a636-758ad2219f5c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 98, 98, 'Your commandments make me wiser than my enemies, for your commandments are always with me.'),
  ('e373ea2e-f8ac-5c86-acd0-57082ae8b182', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 99, 99, 'I have more understanding than all my teachers, for your testimonies are my meditation.'),
  ('d3690cf2-f3f2-56fb-a4d3-fd91ca149032', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 100, 100, 'I understand more than the aged, because I have kept your precepts.'),
  ('94efbbfc-7eec-5621-a4b7-7ae60ad5acb3', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 101, 101, 'I have kept my feet from every evil way, that I might observe your word.'),
  ('c6b30335-2bee-504f-aabe-fd4c217c7d12', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 102, 102, 'I have not turned aside from your ordinances, for you have taught me.'),
  ('bebb327c-4135-5029-a82e-160d1a6b3e58', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 103, 103, 'How sweet are your promises to my taste, more than honey to my mouth!'),
  ('40547997-7da0-5294-aaf0-11bfc231a782', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 104, 104, 'Through your precepts, I get understanding; therefore I hate every false way. NUN'),
  ('5e17ff77-37fb-5f9c-ab8e-8a97814f8435', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 105, 105, 'Your word is a lamp to my feet, and a light for my path.'),
  ('e87c84b5-7fb9-5e19-ac34-8886b90253a7', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 106, 106, 'I have sworn, and have confirmed it, that I will obey your righteous ordinances.'),
  ('adcff6d3-9cb8-5015-a917-43fd39905300', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 107, 107, 'I am afflicted very much. Revive me, Yahweh, according to your word.'),
  ('d85a27b4-d3c3-57b9-a400-597b8cdfdc09', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 108, 108, 'Accept, I beg you, the willing offerings of my mouth. Yahweh, teach me your ordinances.'),
  ('0b8e8cc8-9113-5d4f-a872-4a2c446da541', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 109, 109, 'My soul is continually in my hand, yet I won''t forget your law.'),
  ('0ffa99b8-d40e-5482-a1ac-61fb60d3d746', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 110, 110, 'The wicked have laid a snare for me, yet I haven''t gone astray from your precepts.'),
  ('2ce4eba2-9462-508a-a9c7-5a844c9e80c9', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 111, 111, 'I have taken your testimonies as a heritage forever, for they are the joy of my heart.'),
  ('eeca65a7-7daa-56d6-a168-a8e671ea1582', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 112, 112, 'I have set my heart to perform your statutes forever, even to the end. SAMEKH'),
  ('07d0becc-b028-5c2d-a335-7cb58423c215', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 113, 113, 'I hate double-minded men, but I love your law.'),
  ('68d7f399-4eae-59d0-a18a-a6bde5e321b2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 114, 114, 'You are my hiding place and my shield. I hope in your word.'),
  ('959f7218-13ea-5333-ad5d-8eec50f25078', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 115, 115, 'Depart from me, you evildoers, that I may keep the commandments of my God.'),
  ('b693e3d1-1312-5c44-a077-2eb6fdaabf09', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 116, 116, 'Uphold me according to your word, that I may live. Let me not be ashamed of my hope.'),
  ('b703c3c2-c8d5-521d-a6e3-b3401e45b8ef', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 117, 117, 'Hold me up, and I will be safe, and will have respect for your statutes continually.'),
  ('e3cf642e-1489-5d36-a444-d95ee10c1d92', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 118, 118, 'You reject all those who stray from your statutes, for their deceit is in vain.'),
  ('074e1afb-cebe-503a-a2e2-c010a5b9c69e', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 119, 119, 'You put away all the wicked of the earth like dross. Therefore I love your testimonies.'),
  ('f243a25b-6973-52fb-afec-26ee79ce8341', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 120, 120, 'My flesh trembles for fear of you. I am afraid of your judgments. AYIN'),
  ('86f5c991-1834-536f-ad8f-ae71643b4abc', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 121, 121, 'I have done what is just and righteous. Don''t leave me to my oppressors.'),
  ('3febd424-48b3-552a-ad4b-a5c43010e2ab', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 122, 122, 'Ensure your servant''s well-being. Don''t let the proud oppress me.'),
  ('c29a1424-be73-5300-afbe-99e49b235a87', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 123, 123, 'My eyes fail looking for your salvation, for your righteous word.'),
  ('1b65f096-8543-5321-ad83-6ed458c97c46', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 124, 124, 'Deal with your servant according to your loving kindness. Teach me your statutes.'),
  ('81123929-21d8-5c1b-a933-0212e6520d5b', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 125, 125, 'I am your servant. Give me understanding, that I may know your testimonies.'),
  ('a6db1d02-f031-53d9-a509-5a0183b69e8b', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 126, 126, 'It is time to act, Yahweh, for they break your law.'),
  ('71e8b430-eeb8-5970-afb3-0d6c849ffb3e', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 127, 127, 'Therefore I love your commandments more than gold, yes, more than pure gold.'),
  ('49d458dd-4461-5e63-a387-b095edcde6b2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 128, 128, 'Therefore I consider all of your precepts to be right. I hate every false way. PEY'),
  ('111c3335-0a33-55e0-a859-f0c4a220288a', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 129, 129, 'Your testimonies are wonderful, therefore my soul keeps them.'),
  ('2d14c4a2-b385-547f-abe7-d33b2e529d12', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 130, 130, 'The entrance of your words gives light. It gives understanding to the simple.'),
  ('52ad00e0-3d37-5ca2-af69-454b5de20e5b', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 131, 131, 'I opened my mouth wide and panted, for I longed for your commandments.'),
  ('502509da-bef0-5358-a73f-fc37743ebf34', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 132, 132, 'Turn to me, and have mercy on me, as you always do to those who love your name.'),
  ('a9f5a233-472d-5577-adb7-799b08901c4c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 133, 133, 'Establish my footsteps in your word. Don''t let any iniquity have dominion over me.'),
  ('c22b7fe0-29d5-585a-a0ba-5690dacc231d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 134, 134, 'Redeem me from the oppression of man, so I will observe your precepts.'),
  ('c4018578-1a4c-5f56-a0c3-80a75be84b52', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 135, 135, 'Make your face shine on your servant. Teach me your statutes.'),
  ('05b46dc0-903f-5056-aac5-8957865acdd2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 136, 136, 'Streams of tears run down my eyes, because they don''t observe your law. TZADI'),
  ('b77e0449-d908-50c6-a510-5b8e85d9e0f6', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 137, 137, 'You are righteous, Yahweh. Your judgments are upright.'),
  ('64b7052b-6340-54b7-a42b-4350e4de1bed', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 138, 138, 'You have commanded your statutes in righteousness. They are fully trustworthy.'),
  ('0c5e40fe-db4c-5fa6-a822-d4d6a463cac4', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 139, 139, 'My zeal wears me out, because my enemies ignore your words.'),
  ('1e4d8933-cc22-53cd-a346-9022c156f673', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 140, 140, 'Your promises have been thoroughly tested, and your servant loves them.'),
  ('816474fa-891b-5809-a876-67c996b775c2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 141, 141, 'I am small and despised. I don''t forget your precepts.'),
  ('ec41e69d-819c-57c0-a13a-aeff76f2365d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 142, 142, 'Your righteousness is an everlasting righteousness. Your law is truth.'),
  ('2d20fdd0-2ae5-508a-afc7-ac8c52bad7b6', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 143, 143, 'Trouble and anguish have taken hold of me. Your commandments are my delight.'),
  ('52e01da0-1805-509c-a002-7300179641cb', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 144, 144, 'Your testimonies are righteous forever. Give me understanding, that I may live. KUF'),
  ('dccd6be6-5908-55ba-a4d1-ff6e0f06f0c5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 145, 145, 'I have called with my whole heart. Answer me, Yahweh! I will keep your statutes.'),
  ('ee4da600-d2ab-5986-a507-80967f1ef778', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 146, 146, 'I have called to you. Save me! I will obey your statutes.'),
  ('c30e4d55-efaf-5374-a546-b1535b585ff1', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 147, 147, 'I rise before dawn and cry for help. I put my hope in your words.'),
  ('a0a4162d-b7d1-5e6e-a55d-f715fdc13808', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 148, 148, 'My eyes stay open through the night watches, that I might meditate on your word.'),
  ('9b77a972-d9d2-59cd-ae3a-0e303cdecb14', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 149, 149, 'Hear my voice according to your loving kindness. Revive me, Yahweh, according to your ordinances.'),
  ('dc4b615f-21f3-52e2-a29b-65ecc7668dc4', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 150, 150, 'They draw near who follow after wickedness. They are far from your law.'),
  ('3e545a92-3d9b-5474-a969-e275ef1a78e5', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 151, 151, 'You are near, Yahweh. All your commandments are truth.'),
  ('11354e97-9564-578c-a58f-0ca4353da4a9', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 152, 152, 'Of old I have known from your testimonies, that you have founded them forever. RESH'),
  ('4d936408-96fe-5507-a863-60c080136183', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 153, 153, 'Consider my affliction, and deliver me, for I don''t forget your law.'),
  ('9effc7a6-e2a3-5bdf-a350-9ce93ff6823d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 154, 154, 'Plead my cause, and redeem me! Revive me according to your promise.'),
  ('072cbe05-79ae-591b-a336-9acd1f6069c4', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 155, 155, 'Salvation is far from the wicked, for they don''t seek your statutes.'),
  ('a379e8e2-771d-5788-a746-9ab49d82ac57', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 156, 156, 'Great are your tender mercies, Yahweh. Revive me according to your ordinances.'),
  ('79f4cc44-1ce6-518f-a836-8fcb7cf0f08f', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 157, 157, 'Many are my persecutors and my adversaries. I haven''t swerved from your testimonies.'),
  ('ce7ca526-7ffa-5f52-a3d5-fc50c6887240', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 158, 158, 'I look at the faithless with loathing, because they don''t observe your word.'),
  ('16f886ff-3e10-5561-aebe-9ae6b3ccaa85', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 159, 159, 'Consider how I love your precepts. Revive me, Yahweh, according to your loving kindness.'),
  ('6a77e093-feee-5f83-a2de-6ffc49fbd55e', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 160, 160, 'All of your words are truth. Every one of your righteous ordinances endures forever. SIN AND SHIN'),
  ('ffc40e68-bf36-52e2-ae53-34d4409e670c', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 161, 161, 'Princes have persecuted me without a cause, but my heart stands in awe of your words.'),
  ('9c22b8e0-9039-52fd-a399-9934a92089b9', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 162, 162, 'I rejoice at your word, as one who finds great spoil.'),
  ('0242323c-9e2e-546d-abc4-2f4c4f8bd6b6', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 163, 163, 'I hate and abhor falsehood. I love your law.'),
  ('9329faab-977c-57f3-a7f7-215126f353b1', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 164, 164, 'Seven times a day, I praise you, because of your righteous ordinances.'),
  ('68e0f4af-95fb-5a3c-a7a8-23d57e882054', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 165, 165, 'Those who love your law have great peace. Nothing causes them to stumble.'),
  ('bf6ceda5-d8fc-5c1f-acf7-9645b37b74e0', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 166, 166, 'I have hoped for your salvation, Yahweh. I have done your commandments.'),
  ('9c636c51-9b9d-547d-a145-0da47ce16e23', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 167, 167, 'My soul has observed your testimonies. I love them exceedingly.'),
  ('ea428c35-c4a5-5483-a8d2-1026d94ad203', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 168, 168, 'I have obeyed your precepts and your testimonies, for all my ways are before you. TAV'),
  ('6e653431-bcb9-59cf-a1a2-2aebc8304e4d', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 169, 169, 'Let my cry come before you, Yahweh. Give me understanding according to your word.'),
  ('bced97a8-2ece-5ea0-ad4a-fdbe814fc819', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 170, 170, 'Let my supplication come before you. Deliver me according to your word.'),
  ('5b83a87d-47bc-5a38-a61b-8f8547075739', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 171, 171, 'Let my lips utter praise, for you teach me your statutes.'),
  ('058532ca-db4a-538b-a5f7-dc3ae027efee', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 172, 172, 'Let my tongue sing of your word, for all your commandments are righteousness.'),
  ('35283985-2427-552e-aefc-bb01c23531a9', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 173, 173, 'Let your hand be ready to help me, for I have chosen your precepts.'),
  ('64048ef3-19b9-5343-a915-2d63259301a2', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 174, 174, 'I have longed for your salvation, Yahweh. Your law is my delight.'),
  ('c9a16374-40ce-5536-adf9-722956b4dab3', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 175, 175, 'Let my soul live, that I may praise you. Let your ordinances help me.'),
  ('437a71db-3d95-58c5-aa8f-7eae00df09a8', '19c9a56b-5610-5f4f-ab8e-f5043ccfef47', NULL, 176, 176, 'I have gone astray like a lost sheep. Seek your servant, for I don''t forget your commandments. A Song of Ascents.'),
  ('f940c345-61d3-53ac-a009-2b575cdf92fc', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 1, 1, 'In my distress, I cried to Yahweh. He answered me.'),
  ('b3ceaadd-fc6e-54bc-a9de-638cead67af7', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 2, 2, 'Deliver my soul, Yahweh, from lying lips, from a deceitful tongue.'),
  ('3cd54216-e3e9-5102-a322-dafee947d7c5', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 3, 3, 'What will be given to you, and what will be done more to you, you deceitful tongue?'),
  ('5534bade-33dc-5e0b-a578-e80d985dedba', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 4, 4, 'Sharp arrows of the mighty, with coals of juniper.'),
  ('ba1dc3db-f7d8-5a63-abd0-27041a0fe252', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 5, 5, 'Woe is me, that I live in Meshech, that I dwell among the tents of Kedar!'),
  ('0a100a6c-4f35-5044-a6e9-995e9d0077dc', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 6, 6, 'My soul has had her dwelling too long with him who hates peace.'),
  ('180f4acc-4e32-5107-af57-9835cb629de9', '5913f4e8-f35e-55b6-a1d2-c324347a4d1c', NULL, 7, 7, 'I am for peace, but when I speak, they are for war. A Song of Ascents.'),
  ('da7d5e31-be10-580e-ac8c-049e32315be2', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 1, 1, 'I will lift up my eyes to the hills. Where does my help come from?'),
  ('030e9906-c49b-5238-a631-a069ab9053c7', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 2, 2, 'My help comes from Yahweh, who made heaven and earth.'),
  ('b167970f-be2f-5e6b-ad33-4d3b388fc7e0', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 3, 3, 'He will not allow your foot to be moved. He who keeps you will not slumber.'),
  ('59852ab2-5d73-5ae7-a561-2c01dd758469', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 4, 4, 'Behold, he who keeps Israel will neither slumber nor sleep.'),
  ('6eeedaea-6b1c-566e-a286-144ae3561436', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 5, 5, 'Yahweh is your keeper. Yahweh is your shade on your right hand.'),
  ('1292307d-c3d5-54d1-afd1-c2c0720f2fed', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 6, 6, 'The sun will not harm you by day, nor the moon by night.'),
  ('887f92c6-a249-592c-ae32-c785d3b4da8a', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 7, 7, 'Yahweh will keep you from all evil. He will keep your soul.'),
  ('16750c0d-3213-5959-a8d3-731f6d429801', 'e3f7a390-4032-566a-a6ac-8c496116786e', NULL, 8, 8, 'Yahweh will keep your going out and your coming in, from this time forth, and forevermore. A Song of Ascents. By David.'),
  ('00c6a520-4192-5f52-a242-545cea240287', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 1, 1, 'I was glad when they said to me, "Let''s go to Yahweh''s house!"'),
  ('cd595484-9515-5c19-a917-8ab4e503b5e2', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 2, 2, 'Our feet are standing within your gates, Jerusalem;'),
  ('dd4ec5e8-2ec3-56e0-a72b-d64f93776bcc', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 3, 3, 'Jerusalem, that is built as a city that is compact together;'),
  ('1865c34c-c71e-5f09-afbb-81f718cbf81f', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 4, 4, 'where the tribes go up, even Yah''s tribes, according to an ordinance for Israel, to give thanks to the name of Yahweh.'),
  ('6f2d3f02-47ba-5262-ac08-0fc2e4acd15e', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 5, 5, 'For there are set thrones for judgment, the thrones of David''s house.'),
  ('fe6fa8b7-cd22-5fab-af95-4f853e36fc32', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 6, 6, 'Pray for the peace of Jerusalem. Those who love you will prosper.'),
  ('bb567303-4637-5d07-a615-081977943f1d', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 7, 7, 'Peace be within your walls, and prosperity within your palaces.'),
  ('3cfd3545-1efe-5983-af6a-39fc90809cb9', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 8, 8, 'For my brothers'' and companions'' sakes, I will now say, "Peace be within you."'),
  ('bb73c29d-2867-5de7-a693-1b09f071b017', 'e2b821e6-597a-54a3-a8b7-33e086a01338', NULL, 9, 9, 'For the sake of the house of Yahweh our God, I will seek your good. A Song of Ascents.'),
  ('7e014f66-8b31-5a58-a570-f9a12ae9ec02', 'cded3b31-a60c-5730-a2fd-a3cc0155164a', NULL, 1, 1, 'To you I do lift up my eyes, you who sit in the heavens.'),
  ('8ad582c6-3200-537a-a8fe-f516b6b19c8b', 'cded3b31-a60c-5730-a2fd-a3cc0155164a', NULL, 2, 2, 'Behold, as the eyes of servants look to the hand of their master, as the eyes of a maid to the hand of her mistress; so our eyes look to Yahweh, our God, until he has mercy on us.'),
  ('4fb09bb5-5247-508d-a090-8ebeb5d2efbc', 'cded3b31-a60c-5730-a2fd-a3cc0155164a', NULL, 3, 3, 'Have mercy on us, Yahweh, have mercy on us, for we have endured much contempt.'),
  ('b32a7230-67fd-53e8-a4f3-3f29f084f4b9', 'cded3b31-a60c-5730-a2fd-a3cc0155164a', NULL, 4, 4, 'Our soul is exceedingly filled with the scoffing of those who are at ease, with the contempt of the proud. A Song of Ascents. By David.'),
  ('cdfb6e4e-51d7-5ffc-a614-b64939eaee6e', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 1, 1, 'If it had not been Yahweh who was on our side, let Israel now say,'),
  ('df62d105-693c-53dd-a2c8-aa94e3e924ae', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 2, 2, 'if it had not been Yahweh who was on our side, when men rose up against us;'),
  ('86f22430-1071-5e49-a608-82704593c6f9', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 3, 3, 'then they would have swallowed us up alive, when their wrath was kindled against us;'),
  ('5b2fe144-0722-563b-aa92-015a61c8a7ee', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 4, 4, 'then the waters would have overwhelmed us, the stream would have gone over our soul;'),
  ('a0cb33a6-fa0f-5684-aa48-ed7ac7408dee', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 5, 5, 'then the proud waters would have gone over our soul.'),
  ('654e78c3-baab-56dd-a104-aa72ad78d31c', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 6, 6, 'Blessed be Yahweh, who has not given us as a prey to their teeth.'),
  ('feafee79-2d50-5965-a168-a5d50a58b04e', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 7, 7, 'Our soul has escaped like a bird out of the fowler''s snare. The snare is broken, and we have escaped.'),
  ('ad89f6dd-ab43-5eb4-aa13-2458fc8bf946', '50a7fda6-9744-530c-aebf-42e36626774f', NULL, 8, 8, 'Our help is in the name of Yahweh, who made heaven and earth. A Song of Ascents.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c513f731-806c-5479-a636-98aa2f0ffc4c', '054bc66b-7004-541e-a890-03db7017792c', NULL, 1, 1, 'Those who trust in Yahweh are as Mount Zion, which can''t be moved, but remains forever.'),
  ('ca932d49-f2f0-50b3-a68a-ccbb49c004a8', '054bc66b-7004-541e-a890-03db7017792c', NULL, 2, 2, 'As the mountains surround Jerusalem, so Yahweh surrounds his people from this time forth and forevermore.'),
  ('09b96a84-9924-5051-ae07-f01a0df59974', '054bc66b-7004-541e-a890-03db7017792c', NULL, 3, 3, 'For the scepter of wickedness won''t remain over the allotment of the righteous; so that the righteous won''t use their hands to do evil.'),
  ('b5969bbb-3538-5e09-a538-57bbe84fe7eb', '054bc66b-7004-541e-a890-03db7017792c', NULL, 4, 4, 'Do good, Yahweh, to those who are good, to those who are upright in their hearts.'),
  ('b8dbc6c2-5c84-5adf-af78-aa6ad26cebd5', '054bc66b-7004-541e-a890-03db7017792c', NULL, 5, 5, 'But as for those who turn aside to their crooked ways, Yahweh will lead them away with the workers of iniquity. Peace be on Israel. A Song of Ascents.'),
  ('6f2167fa-ecaa-5d88-afb5-24e2d08d27d9', '61d9a6e0-6391-50fa-acc2-87a269e50cf4', NULL, 1, 1, 'When Yahweh brought back those who returned to Zion, we were like those who dream.'),
  ('31447af0-2648-5cfa-afff-759bebc690c3', '61d9a6e0-6391-50fa-acc2-87a269e50cf4', NULL, 2, 2, 'Then our mouth was filled with laughter, and our tongue with singing. Then they said among the nations, "Yahweh has done great things for them."'),
  ('2dbb4ce2-35ff-5584-aa1d-1cdd6284150d', '61d9a6e0-6391-50fa-acc2-87a269e50cf4', NULL, 3, 3, 'Yahweh has done great things for us, and we are glad.'),
  ('73c86588-a951-527e-ad5e-50f00e059919', '61d9a6e0-6391-50fa-acc2-87a269e50cf4', NULL, 4, 4, 'Restore our fortunes again, Yahweh, like the streams in the Negev.'),
  ('f88bb365-6a49-517b-a079-f88c5ec43265', '61d9a6e0-6391-50fa-acc2-87a269e50cf4', NULL, 5, 5, 'Those who sow in tears will reap in joy.'),
  ('e6ad4c59-1457-552c-aa69-fa70c8607b24', '61d9a6e0-6391-50fa-acc2-87a269e50cf4', NULL, 6, 6, 'He who goes out weeping, carrying seed for sowing, will certainly come again with joy, carrying his sheaves. A Song of Ascents. By Solomon.'),
  ('0b5cb253-a033-5f83-ad3a-025e89104ffc', '3d1b0785-398c-5b86-aa7a-6a4bffa00734', NULL, 1, 1, 'Unless Yahweh builds the house, they labor in vain who build it. Unless Yahweh watches over the city, the watchman guards it in vain.'),
  ('7f02817c-99fc-5dfa-a21f-ac492815ebe3', '3d1b0785-398c-5b86-aa7a-6a4bffa00734', NULL, 2, 2, 'It is vain for you to rise up early, to stay up late, eating the bread of toil; for he gives sleep to his loved ones.'),
  ('9fc51132-f971-59a7-a6e4-4711fda8bfbe', '3d1b0785-398c-5b86-aa7a-6a4bffa00734', NULL, 3, 3, 'Behold, children are a heritage of Yahweh. The fruit of the womb is his reward.'),
  ('ed8f7ee8-82e3-5fb9-ac8f-a1efd74dc218', '3d1b0785-398c-5b86-aa7a-6a4bffa00734', NULL, 4, 4, 'As arrows in the hand of a mighty man, so are the children of youth.'),
  ('845a9082-1979-56ca-a930-6abd68bceed4', '3d1b0785-398c-5b86-aa7a-6a4bffa00734', NULL, 5, 5, 'Happy is the man who has his quiver full of them. They won''t be disappointed when they speak with their enemies in the gate. A Song of Ascents.'),
  ('96485c0f-620a-5472-a573-01c57c25e6d5', '4315a94f-9802-586c-a50a-c74c43cc72ac', NULL, 1, 1, 'Blessed is everyone who fears Yahweh, who walks in his ways.'),
  ('11dfeb2b-8bd0-5292-a6d8-ba47ad6c84f2', '4315a94f-9802-586c-a50a-c74c43cc72ac', NULL, 2, 2, 'For you will eat the labor of your hands. You will be happy, and it will be well with you.'),
  ('46955dfa-8896-5466-a91d-43d02610f99e', '4315a94f-9802-586c-a50a-c74c43cc72ac', NULL, 3, 3, 'Your wife will be as a fruitful vine, in the innermost parts of your house; your children like olive plants, around your table.'),
  ('7b94076a-4336-5bee-a9f4-4fa4d1ad8489', '4315a94f-9802-586c-a50a-c74c43cc72ac', NULL, 4, 4, 'Behold, thus is the man blessed who fears Yahweh.'),
  ('5551d2e3-d24b-5022-af63-541a1d878aea', '4315a94f-9802-586c-a50a-c74c43cc72ac', NULL, 5, 5, 'May Yahweh bless you out of Zion, and may you see the good of Jerusalem all the days of your life.'),
  ('807bd65b-5742-5038-a90a-d81b8ac717e3', '4315a94f-9802-586c-a50a-c74c43cc72ac', NULL, 6, 6, 'Yes, may you see your children''s children. Peace be upon Israel. A Song of Ascents.'),
  ('e15f2c0d-da59-5f44-afdc-6ee93f63ef55', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 1, 1, 'Many times they have afflicted me from my youth up. Let Israel now say,'),
  ('a2afc21b-c763-5895-adbf-3b34ef58ba6f', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 2, 2, 'many times they have afflicted me from my youth up, yet they have not prevailed against me.'),
  ('ad92c7b6-f1bc-5516-a5be-a43e5dc2c625', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 3, 3, 'The plowers plowed on my back. They made their furrows long.'),
  ('45ce5699-4b80-5fd6-aee4-42f5b0cac242', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 4, 4, 'Yahweh is righteous. He has cut apart the cords of the wicked.'),
  ('06e6b10e-94ca-5d92-a757-0a06fb4765e8', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 5, 5, 'Let them be disappointed and turned backward, all those who hate Zion.'),
  ('d2337dca-4787-51a6-ad8f-6f95255dbade', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 6, 6, 'Let them be as the grass on the housetops, which withers before it grows up;'),
  ('94b2df0b-1e1e-5fc3-a07e-771134ba7184', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 7, 7, 'with which the reaper doesn''t fill his hand, nor he who binds sheaves, his bosom.'),
  ('1078ee64-498b-5f1a-a20a-be5f027ca425', 'dbfb09e9-0021-5295-a642-b930f406d070', NULL, 8, 8, 'Neither do those who go by say, "The blessing of Yahweh be on you. We bless you in the name of Yahweh." A Song of Ascents.'),
  ('3cb53ff0-0bb0-5b8f-aa20-dfe3c4eec86a', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 1, 1, 'Out of the depths I have cried to you, Yahweh.'),
  ('493874b0-99ae-5499-a5f9-609f63b1cd77', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 2, 2, 'Lord, hear my voice. Let your ears be attentive to the voice of my petitions.'),
  ('421457c3-adad-5103-a3be-2068ef4f9aa8', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 3, 3, 'If you, Yah, kept a record of sins, Lord, who could stand?'),
  ('7887a827-7464-542c-a809-ffb07cf6b90d', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 4, 4, 'But there is forgiveness with you, therefore you are feared.'),
  ('3ce723d9-4f6a-5e9f-afde-e2774e6fc2c2', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 5, 5, 'I wait for Yahweh. My soul waits. I hope in his word.'),
  ('b453b059-4097-55b6-a786-88692a27a08c', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 6, 6, 'My soul longs for the Lord more than watchmen long for the morning; more than watchmen for the morning.'),
  ('d6b128fa-22db-5a4c-acfb-5d285f2aeb17', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 7, 7, 'Israel, hope in Yahweh, for with Yahweh there is loving kindness. With him is abundant redemption.'),
  ('0531d013-25aa-509b-ae8c-742ac38fdedb', 'd39367b3-8582-504f-ad64-0ad2fbf8da97', NULL, 8, 8, 'He will redeem Israel from all their sins. A Song of Ascents. By David.'),
  ('5657bb6b-951c-535b-a0e0-8962cc4db103', 'f7efedaf-32e9-57a0-ad7c-996b9b2c94f3', NULL, 1, 1, 'Yahweh, my heart isn''t haughty, nor my eyes lofty; nor do I concern myself with great matters, or things too wonderful for me.'),
  ('4ca3dfbc-2218-585b-a628-2b3c46aa6e5c', 'f7efedaf-32e9-57a0-ad7c-996b9b2c94f3', NULL, 2, 2, 'Surely I have stilled and quieted my soul, like a weaned child with his mother, like a weaned child is my soul within me.'),
  ('80981ea9-836c-5113-afbd-3c578fa0447b', 'f7efedaf-32e9-57a0-ad7c-996b9b2c94f3', NULL, 3, 3, 'Israel, hope in Yahweh, from this time forth and forevermore. A Song of Ascents.'),
  ('00c3772d-5602-5a78-ac67-dc24617bf8fc', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 1, 1, 'Yahweh, remember David and all his affliction,'),
  ('e980ff5c-e1ea-58ff-ad4e-8435f08d2b5c', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 2, 2, 'how he swore to Yahweh, and vowed to the Mighty One of Jacob:'),
  ('da6b28e7-7241-58db-a2b8-40136a7d3c03', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 3, 3, '"Surely I will not come into the structure of my house, nor go up into my bed;'),
  ('4bf99862-44a7-5631-a9ea-a987f7aca705', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 4, 4, 'I will not give sleep to my eyes, or slumber to my eyelids;'),
  ('9faef191-8b62-542b-a093-d770745b366c', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 5, 5, 'until I find out a place for Yahweh, a dwelling for the Mighty One of Jacob."'),
  ('51f0720d-f9f0-5e9d-a30c-688917b5dec1', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 6, 6, 'Behold, we heard of it in Ephrathah. We found it in the field of Jaar:'),
  ('bb167658-aa3e-591e-a660-0f8b88c376ad', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 7, 7, '"We will go into his dwelling place. We will worship at his footstool.'),
  ('8c2515b9-d5db-50fc-a7e7-189ffb7f0451', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 8, 8, 'Arise, Yahweh, into your resting place; you, and the ark of your strength.'),
  ('52261581-294d-5e2a-a861-28ff11f9f963', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 9, 9, 'Let your priest be clothed with righteousness. Let your saints shout for joy!"'),
  ('1bc34283-d2c2-5067-aca6-53540a45c415', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 10, 10, 'For your servant David''s sake, don''t turn away the face of your anointed one.'),
  ('1b66d39a-0be4-59f8-a9ad-801a569632ba', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 11, 11, 'Yahweh has sworn to David in truth. He will not turn from it: "I will set the fruit of your body on your throne.'),
  ('6dde8c6b-7969-5737-a90f-17f1f829b133', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 12, 12, 'If your children will keep my covenant, my testimony that I will teach them, their children also will sit on your throne forevermore."'),
  ('4f4045ec-111c-5dbb-a844-909de6602924', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 13, 13, 'For Yahweh has chosen Zion. He has desired it for his habitation.'),
  ('b22e5bb8-ebe2-5070-a619-8f19ec3a671b', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 14, 14, '"This is my resting place forever. Here I will live, for I have desired it.'),
  ('f4cc308c-bdfa-501e-a82f-57409a69844f', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 15, 15, 'I will abundantly bless her provision. I will satisfy her poor with bread.'),
  ('3123991e-a358-59ab-ab68-9514aae78cff', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 16, 16, 'Her priests I will also clothe with salvation. Her saints will shout aloud for joy.'),
  ('fa91ef6a-d054-5cd2-a69c-39d1d8044ea2', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 17, 17, 'There I will make the horn of David to bud. I have ordained a lamp for my anointed.'),
  ('2988b140-c3c0-53c0-a5c6-d7ae6fd8e3cc', '096b77f4-fa3b-582c-a582-57e1f752ea90', NULL, 18, 18, 'I will clothe his enemies with shame, but on himself, his crown will be resplendent." A Song of Ascents. By David.'),
  ('fa76f8a3-4cab-5be7-aa3a-afeeaa03993d', 'b304ece1-852e-55b6-ad20-d8d530b87430', NULL, 1, 1, 'See how good and how pleasant it is for brothers to live together in unity!'),
  ('a6502386-2863-5c59-a984-f196fd04e7cd', 'b304ece1-852e-55b6-ad20-d8d530b87430', NULL, 2, 2, 'It is like the precious oil on the head, that ran down on the beard, even Aaron''s beard; that came down on the edge of his robes;'),
  ('c410e36a-797a-5a26-a18f-3f5fe8a74f69', 'b304ece1-852e-55b6-ad20-d8d530b87430', NULL, 3, 3, 'like the dew of Hermon, that comes down on the hills of Zion: for there Yahweh gives the blessing, even life forevermore. A Song of Ascents.'),
  ('e5b0b3ab-55bf-5fa0-a446-86acc064d27a', '195109c5-7bd7-5117-ac27-d4d6fe6b3d72', NULL, 1, 1, 'Look! Praise Yahweh, all you servants of Yahweh, who stand by night in Yahweh''s house!'),
  ('bf236b43-0694-5d0c-a366-316217988456', '195109c5-7bd7-5117-ac27-d4d6fe6b3d72', NULL, 2, 2, 'Lift up your hands in the sanctuary. Praise Yahweh!'),
  ('41597f2b-d835-55e3-a618-47de2ce86dd2', '195109c5-7bd7-5117-ac27-d4d6fe6b3d72', NULL, 3, 3, 'May Yahweh bless you from Zion; even he who made heaven and earth.'),
  ('3e7dd7b4-65cf-53ab-a9ff-ee5f35a4d435', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 1, 1, 'Praise Yah! Praise the name of Yahweh! Praise him, you servants of Yahweh,'),
  ('3ddc0542-a9d0-5852-a4a0-8dc8a79151d2', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 2, 2, 'you who stand in the house of Yahweh, in the courts of our God''s house.'),
  ('92d929e7-0f73-5cf8-aaa4-f02b448a295e', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 3, 3, 'Praise Yah, for Yahweh is good. Sing praises to his name, for that is pleasant.'),
  ('04a0aef7-b1cf-503e-a53e-9fca19b347e3', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 4, 4, 'For Yah has chosen Jacob for himself; Israel for his own possession.'),
  ('77133de2-d3f1-58a3-a354-607dcda314a2', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 5, 5, 'For I know that Yahweh is great, that our Lord is above all gods.'),
  ('24ca2edc-0f94-586e-accd-b43968a2151d', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 6, 6, 'Whatever Yahweh pleased, that he has done, in heaven and in earth, in the seas and in all deeps;'),
  ('a40cd763-c162-5868-a0ee-0f4a86c6ff9d', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 7, 7, 'who causes the clouds to rise from the ends of the earth; who makes lightnings with the rain; who brings forth the wind out of his treasuries;'),
  ('b63bf052-38b2-519f-ae6b-ab809ce4991a', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 8, 8, 'Who struck the firstborn of Egypt, both of man and animal;'),
  ('6d682917-7200-5aba-a128-4d82e86711c1', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 9, 9, 'Who sent signs and wonders into the midst of you, Egypt, on Pharaoh, and on all his servants;'),
  ('b7410ff1-6f09-51cf-a52c-814a85783c0d', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 10, 10, 'who struck many nations, and killed mighty kings,'),
  ('9ece8945-4895-5d59-a815-0a74dbc619bf', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 11, 11, 'Sihon king of the Amorites, Og king of Bashan, and all the kingdoms of Canaan,'),
  ('3021c7be-759d-5ab7-ac77-efec9a310f67', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 12, 12, 'and gave their land for a heritage, a heritage to Israel, his people.'),
  ('0ef93e28-bed4-57d6-a245-467a8cc23796', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 13, 13, 'Your name, Yahweh, endures forever; your renown, Yahweh, throughout all generations.'),
  ('3417196b-2e3a-5d34-ac2a-31c8749c0d9e', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 14, 14, 'For Yahweh will judge his people, and have compassion on his servants.'),
  ('17af2c31-2d1e-54a3-aff4-ec0071ffaab4', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 15, 15, 'The idols of the nations are silver and gold, the work of men''s hands.'),
  ('3db9c9bf-f2f4-516a-a1f2-594a54084aff', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 16, 16, 'They have mouths, but they can''t speak. They have eyes, but they can''t see.'),
  ('be8f2c6d-841a-56be-ab20-5202f46de2cf', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 17, 17, 'They have ears, but they can''t hear; neither is there any breath in their mouths.'),
  ('40557c4c-eb15-545c-a8a1-6e3352986eaa', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 18, 18, 'Those who make them will be like them; yes, everyone who trusts in them.'),
  ('23068343-2e99-5201-a26e-c1f5227f1d51', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 19, 19, 'House of Israel, praise Yahweh! House of Aaron, praise Yahweh!'),
  ('6cbf04c8-e2f9-5925-a086-cfe896be2c31', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 20, 20, 'House of Levi, praise Yahweh! You who fear Yahweh, praise Yahweh!'),
  ('592da08b-55ce-5544-a3d5-0bc0f3004916', '0d81881f-076a-57e5-afa9-b88b050a7c4f', NULL, 21, 21, 'Blessed be Yahweh from Zion, Who dwells at Jerusalem. Praise Yah!'),
  ('82937690-f10a-50a9-a10a-4a564d3ff2f0', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 1, 1, 'Give thanks to Yahweh, for he is good; for his loving kindness endures forever.'),
  ('7e8f70e6-bbab-505e-ad5a-0333b6112e4e', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 2, 2, 'Give thanks to the God of gods; for his loving kindness endures forever.'),
  ('d00daacd-c66d-5066-a686-2bcab1df5d65', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 3, 3, 'Give thanks to the Lord of lords; for his loving kindness endures forever:'),
  ('0475a159-93e5-509b-a188-d6ab1a7b4ca9', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 4, 4, 'To him who alone does great wonders; for his loving kindness endures forever:'),
  ('5b2ee1f3-d23f-5e92-a343-51c0925766e8', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 5, 5, 'To him who by understanding made the heavens; for his loving kindness endures forever:'),
  ('3ea17af5-97f3-5b1e-a937-f70781cd4d8a', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 6, 6, 'To him who spread out the earth above the waters; for his loving kindness endures forever:'),
  ('a4ac4aca-ea5d-5dcd-a430-2abd678aa0ae', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 7, 7, 'To him who made the great lights; for his loving kindness endures forever:'),
  ('279f9990-78ae-541b-a479-c8e2c3bf9379', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 8, 8, 'The sun to rule by day; for his loving kindness endures forever;'),
  ('51e94c58-18f1-5172-a4b5-b13a31a1db19', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 9, 9, 'The moon and stars to rule by night; for his loving kindness endures forever:'),
  ('5003d795-17ab-58b7-aa1e-724801065c1b', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 10, 10, 'To him who struck down the Egyptian firstborn; for his loving kindness endures forever;'),
  ('f42060dd-add4-5483-ab6e-c3f7ab94c2d5', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 11, 11, 'And brought out Israel from among them; for his loving kindness endures forever;'),
  ('9bce28b8-3788-537b-a24a-015ee87cdebb', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 12, 12, 'With a strong hand, and with an outstretched arm; for his loving kindness endures forever:'),
  ('f727a1f8-7ba5-59a3-af7b-468becac9791', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 13, 13, 'To him who divided the Red Sea apart; for his loving kindness endures forever;'),
  ('30ef934a-ab76-5bb6-ac3b-f32e99d713ea', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 14, 14, 'And made Israel to pass through its midst; for his loving kindness endures forever;'),
  ('c4e4e7b2-82f3-59d2-ad6c-0cf9607f234a', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 15, 15, 'But overthrew Pharaoh and his army in the Red Sea; for his loving kindness endures forever:'),
  ('ae2bfc16-52ac-5d7c-acd4-0e93c76264f0', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 16, 16, 'To him who led his people through the wilderness; for his loving kindness endures forever:'),
  ('96b6ac80-8a92-5be0-a8bf-3092340e0d7b', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 17, 17, 'To him who struck great kings; for his loving kindness endures forever;'),
  ('1d9e4e38-e0a0-5674-a0bd-a4d2dd3dbd64', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 18, 18, 'And killed mighty kings; for his loving kindness endures forever:'),
  ('c89f80a0-3896-53b5-a8d8-05814c28baf0', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 19, 19, 'Sihon king of the Amorites; for his loving kindness endures forever;'),
  ('3310e1d9-5e0d-5963-a55d-1a0122e8c6a2', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 20, 20, 'Og king of Bashan; for his loving kindness endures forever;'),
  ('eeeb5a1d-53ad-5282-a281-cf9fafc4e180', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 21, 21, 'And gave their land as an inheritance; for his loving kindness endures forever;'),
  ('cf47a498-1c03-5207-a9c6-f4ab922ceaac', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 22, 22, 'Even a heritage to Israel his servant; for his loving kindness endures forever:'),
  ('80b4170b-fed5-5819-a7ff-201896e06195', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 23, 23, 'Who remembered us in our low estate; for his loving kindness endures forever;'),
  ('e509d4ae-1ca1-5a7d-a2ea-ecad1d776736', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 24, 24, 'And has delivered us from our adversaries; for his loving kindness endures forever:'),
  ('45c651c7-d383-5fdb-a39c-2f291d113289', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 25, 25, 'Who gives food to every creature; for his loving kindness endures forever.'),
  ('3501fcb6-99a5-5802-a06c-737c28d0c14d', '7d348d41-6b4d-5445-af2a-e44a451229aa', NULL, 26, 26, 'Oh give thanks to the God of heaven; for his loving kindness endures forever.'),
  ('f6bc0789-304c-56c9-a31c-06fbf4d9e8eb', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 1, 1, 'By the rivers of Babylon, there we sat down. Yes, we wept, when we remembered Zion.'),
  ('53cf2b14-2fee-5a58-aa5b-2cb66c13dc46', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 2, 2, 'On the willows in its midst, we hung up our harps.'),
  ('2141ea88-19ba-51d3-ad08-1db63a82c75b', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 3, 3, 'For there, those who led us captive asked us for songs. Those who tormented us demanded songs of joy: "Sing us one of the songs of Zion!"'),
  ('9912b591-e155-5a99-a631-2ef93e66a81a', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 4, 4, 'How can we sing Yahweh''s song in a foreign land?'),
  ('bc6a72b3-0a85-56f2-a1ca-d2c771a1ee9b', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 5, 5, 'If I forget you, Jerusalem, let my right hand forget its skill.'),
  ('3900ec68-3129-5b20-a6f4-076bf860f449', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 6, 6, 'Let my tongue stick to the roof of my mouth if I don''t remember you; if I don''t prefer Jerusalem above my chief joy.'),
  ('89591751-7818-5cd4-ab80-86b90a7e4ebd', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 7, 7, 'Remember, Yahweh, against the children of Edom, the day of Jerusalem; who said, "Raze it! Raze it even to its foundation!"'),
  ('c7419ce1-f4b8-5445-ab23-454fe6fdcd32', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 8, 8, 'Daughter of Babylon, doomed to destruction, he will be happy who rewards you, as you have served us.'),
  ('3fa97d36-03b0-5ede-a8e4-d2085bfa134c', '96db45db-0428-52d1-afd4-b64aa4d2994f', NULL, 9, 9, 'Happy shall he be, who takes and dashes your little ones against the rock. By David.'),
  ('205a6b37-fd43-5494-a0be-f0141d3886fe', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 1, 1, 'I will give you thanks with my whole heart. Before the gods, I will sing praises to you.'),
  ('19e578f6-29a5-5f28-a5ff-12c61da94f31', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 2, 2, 'I will bow down toward your holy temple, and give thanks to your Name for your loving kindness and for your truth; for you have exalted your Name and your Word above all.'),
  ('befcd26b-4080-52be-a76b-54c0c1ec29d6', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 3, 3, 'In the day that I called, you answered me. You encouraged me with strength in my soul.'),
  ('3cce6ac0-71c6-5ef7-a6ed-5273e5f210ab', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 4, 4, 'All the kings of the earth will give you thanks, Yahweh, for they have heard the words of your mouth.'),
  ('8081bd36-a753-5bcf-ab7a-b782ad440bdc', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 5, 5, 'Yes, they will sing of the ways of Yahweh; for great is Yahweh''s glory.'),
  ('5a1704cf-23f8-591d-af63-a225812227c0', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 6, 6, 'For though Yahweh is high, yet he looks after the lowly; but the proud, he knows from afar.'),
  ('0ea4f78c-6d19-5032-a874-54e165b2ca2b', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 7, 7, 'Though I walk in the midst of trouble, you will revive me. You will stretch forth your hand against the wrath of my enemies. Your right hand will save me.'),
  ('b070de79-c9b0-5a6d-a32e-e3537a75b6a3', '6882520e-7190-5561-a509-c5a4318b3541', NULL, 8, 8, 'Yahweh will fulfill that which concerns me; your loving kindness, Yahweh, endures forever. Don''t forsake the works of your own hands. For the Chief Musician. A Psalm by David.'),
  ('d6bbb623-6833-5d53-a5df-b5cae6a70748', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 1, 1, 'Yahweh, you have searched me, and you know me.'),
  ('9d55a16b-059a-5faf-aa92-c725a858b864', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 2, 2, 'You know my sitting down and my rising up. You perceive my thoughts from afar.'),
  ('52c3f145-142d-5783-a0e4-61e6b48f59b7', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 3, 3, 'You search out my path and my lying down, and are acquainted with all my ways.'),
  ('2b2b56e0-5ee4-557c-aa5f-64722f6fc4e5', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 4, 4, 'For there is not a word on my tongue, but, behold, Yahweh, you know it altogether.'),
  ('8e067eaf-8621-5249-a5fe-9b78ff850c71', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 5, 5, 'You hem me in behind and before. You laid your hand on me.'),
  ('33e41f17-dd39-565a-a587-539531774472', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 6, 6, 'This knowledge is beyond me. It''s lofty. I can''t attain it.'),
  ('caf608b8-259d-55df-a45a-3bcb7847c931', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 7, 7, 'Where could I go from your Spirit? Or where could I flee from your presence?'),
  ('520041a4-0cd2-5719-a112-8b2a4031146e', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 8, 8, 'If I ascend up into heaven, you are there. If I make my bed in Sheol, behold, you are there!'),
  ('85eb00fe-4b09-5ec3-a404-26f9f2a8145b', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 9, 9, 'If I take the wings of the dawn, and settle in the uttermost parts of the sea;'),
  ('e27343fe-82ee-5a00-a28f-9aaaed175bd6', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 10, 10, 'Even there your hand will lead me, and your right hand will hold me.'),
  ('c4b1a2f6-557b-59d8-ac20-71ca7726b81f', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 11, 11, 'If I say, "Surely the darkness will overwhelm me; the light around me will be night;"'),
  ('f94005c2-e2fd-5d4a-abab-22fa49942625', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 12, 12, 'even the darkness doesn''t hide from you, but the night shines as the day. The darkness is like light to you.'),
  ('5833c656-3328-5c9d-ab02-93e5b06b20bc', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 13, 13, 'For you formed my inmost being. You knit me together in my mother''s womb.'),
  ('08208dfe-7241-5ba9-a31d-8e04776eeb9d', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 14, 14, 'I will give thanks to you, for I am fearfully and wonderfully made. Your works are wonderful. My soul knows that very well.'),
  ('41d96bef-e6cf-51a2-aa5c-23476c7e68f7', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 15, 15, 'My frame wasn''t hidden from you, when I was made in secret, woven together in the depths of the earth.'),
  ('4a0c7784-777a-5b5c-a442-4386e99ef781', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 16, 16, 'Your eyes saw my body. In your book they were all written, the days that were ordained for me, when as yet there were none of them.'),
  ('bb3a89a7-eecb-5409-a602-4201a318c5b9', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 17, 17, 'How precious to me are your thoughts, God! How vast is the sum of them!'),
  ('45a3231a-9bda-55e9-a486-a8ddf9ea8a2f', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 18, 18, 'If I would count them, they are more in number than the sand. When I wake up, I am still with you.'),
  ('6da62626-91d7-5351-a631-54b822562233', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 19, 19, 'If only you, God, would kill the wicked. Get away from me, you bloodthirsty men!'),
  ('4e7688b0-9006-5330-a873-c5f27fa8c6f9', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 20, 20, 'For they speak against you wickedly. Your enemies take your name in vain.'),
  ('ebdba893-1453-562c-a663-5fba15801e53', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 21, 21, 'Yahweh, don''t I hate those who hate you? Am I not grieved with those who rise up against you?'),
  ('b5bd18fb-324d-51d0-a7ff-acbc33439bad', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 22, 22, 'I hate them with perfect hatred. They have become my enemies.'),
  ('1ff5ff20-dc2d-59fd-a88a-e9dfd6617374', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 23, 23, 'Search me, God, and know my heart. Try me, and know my thoughts.'),
  ('5cb09a46-7f80-5a3a-ae19-100184914eb7', '27e3c15e-cdd2-5915-a610-4cbc2d26113b', NULL, 24, 24, 'See if there is any wicked way in me, and lead me in the everlasting way. For the Chief Musician. A Psalm by David.'),
  ('6316b43c-3f74-52ac-a79e-bef7dd1df75e', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 1, 1, 'Deliver me, Yahweh, from the evil man. Preserve me from the violent man;'),
  ('4ae149b2-5d34-5442-a0bb-076e062f2097', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 2, 2, 'those who devise mischief in their hearts. They continually gather themselves together for war.'),
  ('2ea69fa9-0793-5839-a1be-39818a7c2b73', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 3, 3, 'They have sharpened their tongues like a serpent. Viper''s poison is under their lips. Selah.'),
  ('3cef6fec-1b4b-5b6f-aab4-5c403d5091a6', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 4, 4, 'Yahweh, keep me from the hands of the wicked. Preserve me from the violent men who have determined to trip my feet.'),
  ('6b5a4c15-7a6e-5831-a141-97fe72b049ad', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 5, 5, 'The proud have hidden a snare for me, they have spread the cords of a net by the path. They have set traps for me. Selah.'),
  ('76dd42a9-e5a6-5a6b-a5ac-ad212c89ba84', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 6, 6, 'I said to Yahweh, "You are my God." Listen to the cry of my petitions, Yahweh.'),
  ('dcf60dc2-01af-5c4d-ac7f-e505cede0e78', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 7, 7, 'Yahweh, the Lord, the strength of my salvation, you have covered my head in the day of battle.'),
  ('d096afe1-a6a3-5a04-a7a2-d2ff5c7b6925', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 8, 8, 'Yahweh, don''t grant the desires of the wicked. Don''t let their evil plans succeed, or they will become proud. Selah.'),
  ('9fbc357e-1c1f-5a7b-a6f4-ce1e158c712c', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 9, 9, 'As for the head of those who surround me, let the mischief of their own lips cover them.'),
  ('84155713-5273-51e5-a7b9-c7ec0e55f366', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 10, 10, 'Let burning coals fall on them. Let them be thrown into the fire, into miry pits, from where they never rise.'),
  ('b4736b35-0d14-563a-a18a-20db28c2fd23', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 11, 11, 'An evil speaker won''t be established in the earth. Evil will hunt the violent man to overthrow him.'),
  ('905ee5d9-00c1-537e-a859-290aab5f25dc', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 12, 12, 'I know that Yahweh will maintain the cause of the afflicted, and justice for the needy.'),
  ('653821d1-00b7-50ff-a4a9-23415465f445', 'cd71d45c-c351-594a-adc5-e00c70ee0647', NULL, 13, 13, 'Surely the righteous will give thanks to your name. The upright will dwell in your presence. A Psalm by David.'),
  ('25f9634f-54ce-52b8-a639-b65f31772588', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 1, 1, 'Yahweh, I have called on you. Come to me quickly! Listen to my voice when I call to you.'),
  ('31e50305-b4c3-5690-a366-8bb5f14dfb81', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 2, 2, 'Let my prayer be set before you like incense; the lifting up of my hands like the evening sacrifice.'),
  ('3d8b7cb9-0c25-548b-a421-d4f2e2e6d801', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 3, 3, 'Set a watch, Yahweh, before my mouth. Keep the door of my lips.'),
  ('9c59bf30-45d1-5029-ac6d-644d92cdaba9', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 4, 4, 'Don''t incline my heart to any evil thing, to practice deeds of wickedness with men who work iniquity. Don''t let me eat of their delicacies.'),
  ('cac0bea7-f6a5-5aa8-a782-efa4184a9463', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 5, 5, 'Let the righteous strike me, it is kindness; let him reprove me, it is like oil on the head; don''t let my head refuse it; Yet my prayer is always against evil deeds.'),
  ('89b07882-7e4b-5e85-abb0-8676bfb5369f', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 6, 6, 'Their judges are thrown down by the sides of the rock. They will hear my words, for they are well spoken.'),
  ('c9a641b9-652d-5b46-a8c9-d890cbc19c26', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 7, 7, '"As when one plows and breaks up the earth, our bones are scattered at the mouth of Sheol."'),
  ('1213c6c3-d2db-5389-a163-76d60556d6d6', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 8, 8, 'For my eyes are on you, Yahweh, the Lord. In you, I take refuge. Don''t leave my soul destitute.'),
  ('650f6a7e-f041-5b75-acc6-35f158030b07', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 9, 9, 'Keep me from the snare which they have laid for me, from the traps of the workers of iniquity.'),
  ('fb4245b3-2fd4-5031-ac39-3bc7d833059b', 'd1db8484-c0dd-5ec4-a880-ccf7b6f5678f', NULL, 10, 10, 'Let the wicked fall together into their own nets, while I pass by. A contemplation by David, when he was in the cave. A Prayer.'),
  ('aa70227e-a1e3-562b-a999-0e99046d324f', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 1, 1, 'I cry with my voice to Yahweh. With my voice, I ask Yahweh for mercy.'),
  ('29ed62b2-063b-57ad-adc5-78c555237719', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 2, 2, 'I pour out my complaint before him. I tell him my troubles.'),
  ('bacea2e6-e7b7-5db5-a270-1662d2b4f362', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 3, 3, 'When my spirit was overwhelmed within me, you knew my path. In the way in which I walk, they have hidden a snare for me.'),
  ('48a765f1-00db-5811-a8d9-9359783fb88c', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 4, 4, 'Look on my right, and see; for there is no one who is concerned for me. Refuge has fled from me. No one cares for my soul.'),
  ('5ba20d3f-2441-50c2-ab85-2a362833846c', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 5, 5, 'I cried to you, Yahweh. I said, "You are my refuge, my portion in the land of the living."'),
  ('6c7a46f7-1e8e-51a5-a7a3-82f06d58e6cf', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 6, 6, 'Listen to my cry, for I am in desperate need. deliver me from my persecutors, For they are stronger than me.'),
  ('6a00e128-f72b-50f1-a3d1-8fb4d586eb8b', 'f8c59883-3fcd-534f-ae0d-40092dd9d396', NULL, 7, 7, 'Bring my soul out of prison, that I may give thanks to your name. The righteous will surround me, for you will be good to me. A Psalm by David.'),
  ('fde2a90c-c616-5e03-ad02-4b6c4f7ac9b4', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 1, 1, 'Hear my prayer, Yahweh. Listen to my petitions. In your faithfulness and righteousness, relieve me.'),
  ('089a8007-4b1c-5932-a1c7-ff1905471780', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 2, 2, 'Don''t enter into judgment with your servant, for in your sight no man living is righteous.'),
  ('5ea773bb-e8a5-552e-a505-10e5456e486b', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 3, 3, 'For the enemy pursues my soul. He has struck my life down to the ground. He has made me live in dark places, as those who have been long dead.'),
  ('678e7a27-50af-524f-a03c-42f4ab7a8823', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 4, 4, 'Therefore my spirit is overwhelmed within me. My heart within me is desolate.'),
  ('60d1b172-9ef1-52ca-a633-d29ae202de47', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 5, 5, 'I remember the days of old. I meditate on all your doings. I contemplate the work of your hands.'),
  ('2273a808-41e1-5a83-af17-30906e89f55c', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 6, 6, 'I spread forth my hands to you. My soul thirsts for you, like a parched land. Selah.'),
  ('9ccf4b04-7032-5ecc-ab14-1d9210c540e8', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 7, 7, 'Hurry to answer me, Yahweh. My spirit fails. Don''t hide your face from me, so that I don''t become like those who go down into the pit.'),
  ('7964fdbd-85b3-503a-a12e-46e7375662f8', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 8, 8, 'Cause me to hear your loving kindness in the morning, for I trust in you. Cause me to know the way in which I should walk, for I lift up my soul to you.'),
  ('63386a79-0b35-5b77-a2fd-0ca0c0f4f8af', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 9, 9, 'Deliver me, Yahweh, from my enemies. I flee to you to hide me.'),
  ('4f73ae84-25d2-5e21-acba-13f8f4ede288', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 10, 10, 'Teach me to do your will, for you are my God. Your Spirit is good. Lead me in the land of uprightness.'),
  ('8e6db6d3-832e-5a83-a8f2-2ab933c10b81', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 11, 11, 'Revive me, Yahweh, for your name''s sake. In your righteousness, bring my soul out of trouble.'),
  ('fd7fb8c1-1c96-5fe6-aaa6-e19944265e8a', '8b6a088d-1403-5954-a65d-5d3b6f046ec8', NULL, 12, 12, 'In your loving kindness, cut off my enemies, and destroy all those who afflict my soul, For I am your servant. By David.'),
  ('a121a633-0eaf-5963-a083-d889ee80abf4', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 1, 1, 'Blessed be Yahweh, my rock, who teaches my hands to war, and my fingers to battle:'),
  ('831d23ba-c053-5d7f-a099-50926577774c', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 2, 2, 'my loving kindness, my fortress, my high tower, my deliverer, my shield, and he in whom I take refuge; who subdues my people under me.'),
  ('14055c22-20a0-5c8e-aff9-62f172775a15', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 3, 3, 'Yahweh, what is man, that you care for him? Or the son of man, that you think of him?'),
  ('e1482483-f9c5-5f83-a4bb-8c323d785d35', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 4, 4, 'Man is like a breath. His days are like a shadow that passes away.'),
  ('3a671571-a98a-533c-af33-d66463c7388f', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 5, 5, 'Part your heavens, Yahweh, and come down. Touch the mountains, and they will smoke.'),
  ('e9bf1c18-5c38-5b5d-a861-3b92f5444696', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 6, 6, 'Throw out lightning, and scatter them. Send out your arrows, and rout them.'),
  ('f50cb5c9-4e3c-502f-a5e2-3fc61fd9dd47', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 7, 7, 'Stretch out your hand from above, rescue me, and deliver me out of great waters, out of the hands of foreigners;'),
  ('5c7065c3-9a19-5af3-a63c-2c90abfdf07c', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 8, 8, 'whose mouths speak deceit, Whose right hand is a right hand of falsehood.'),
  ('2af39894-514c-5610-aa21-e65c4564d620', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 9, 9, 'I will sing a new song to you, God. On a ten-stringed lyre, I will sing praises to you.'),
  ('35d79136-820b-5f56-a276-1bebd0e0af06', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 10, 10, 'You are he who gives salvation to kings, who rescues David, his servant, from the deadly sword.'),
  ('0f0470b9-eac5-5bb0-a672-e15531d25bb3', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 11, 11, 'Rescue me, and deliver me out of the hands of foreigners, whose mouths speak deceit, whose right hand is a right hand of falsehood.'),
  ('e22d65c0-168a-5da9-a35d-b6c4a74277d2', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 12, 12, 'Then our sons will be like well-nurtured plants, our daughters like pillars carved to adorn a palace.'),
  ('10742035-35e7-56fa-aa74-98325736b8b8', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 13, 13, 'Our barns are full, filled with all kinds of provision. Our sheep bring forth thousands and ten thousands in our fields.'),
  ('d157a998-c630-5dc8-af4d-807f18682814', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 14, 14, 'Our oxen will pull heavy loads. There is no breaking in, and no going away, and no outcry in our streets.'),
  ('b33c3d57-0eef-58a4-a9c3-84741bd2a222', '0eda5890-8adf-5bbc-a173-5319b64751f5', NULL, 15, 15, 'Happy are the people who are in such a situation. Happy are the people whose God is Yahweh. A praise psalm by David.'),
  ('0b99d34a-6d80-5fec-a147-dce9551aab3b', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 1, 1, 'I will exalt you, my God, the King. I will praise your name forever and ever.'),
  ('f92dc01a-1a34-5857-aa22-f18f3a6f3728', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 2, 2, 'Every day I will praise you. I will extol your name forever and ever.'),
  ('a136f26f-73a6-59ca-a3b4-eba81f920efb', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 3, 3, 'Great is Yahweh, and greatly to be praised! His greatness is unsearchable.'),
  ('0f80ee54-af5c-5a39-a5d0-dd2d88960022', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 4, 4, 'One generation will commend your works to another, and will declare your mighty acts.'),
  ('2b907a92-bf56-51da-a5d9-7dd2ed9d1ea0', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 5, 5, 'Of the glorious majesty of your honor, of your wondrous works, I will meditate.'),
  ('93f74623-a65e-565e-a58b-f1f7da5c7a20', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 6, 6, 'Men will speak of the might of your awesome acts. I will declare your greatness.'),
  ('00a60629-c577-590c-a771-63ea3695dc45', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 7, 7, 'They will utter the memory of your great goodness, and will sing of your righteousness.'),
  ('33ead6c6-d8f7-5c50-a93a-fddd991ae410', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 8, 8, 'Yahweh is gracious, merciful, slow to anger, and of great loving kindness.'),
  ('02052267-927d-59fe-a10a-de8c18ee2ae6', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 9, 9, 'Yahweh is good to all. His tender mercies are over all his works.'),
  ('bc0c6c8b-4fcc-5c0d-a2fe-ff292d625652', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 10, 10, 'All your works will give thanks to you, Yahweh. Your saints will extol you.'),
  ('0462676e-b84f-5387-a5ea-2b7c6cee4c7d', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 11, 11, 'They will speak of the glory of your kingdom, and talk about your power;'),
  ('eb503ac8-30b3-5bde-a056-dc9d1d70e8cf', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 12, 12, 'to make known to the sons of men his mighty acts, the glory of the majesty of his kingdom.'),
  ('78de4ed5-20cb-59a3-a3b3-08abd91004de', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 13, 13, 'Your kingdom is an everlasting kingdom. Your dominion endures throughout all generations. Yahweh is faithful in all his words, and loving in all his deeds.'),
  ('b4cb6129-c2a4-592d-a255-74d52f66e0b9', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 14, 14, 'Yahweh upholds all who fall, and raises up all those who are bowed down.'),
  ('db8524ae-ad7f-5016-a352-15fa10f86cd1', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 15, 15, 'The eyes of all wait for you. You give them their food in due season.'),
  ('f20724df-5423-5e63-a0ce-9718181c0fc1', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 16, 16, 'You open your hand, and satisfy the desire of every living thing.'),
  ('381b44ab-0f5e-53f7-ac7f-ede595b57ab5', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 17, 17, 'Yahweh is righteous in all his ways, and gracious in all his works.'),
  ('d408a01b-cbb0-57d7-ae6f-eb8b990835e3', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 18, 18, 'Yahweh is near to all those who call on him, to all who call on him in truth.'),
  ('1b026a50-86c1-5ea2-a2b7-2971c10875fb', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 19, 19, 'He will fulfill the desire of those who fear him. He also will hear their cry, and will save them.'),
  ('fb2ee268-44c9-5111-af9a-cdee247a128b', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 20, 20, 'Yahweh preserves all those who love him, but all the wicked he will destroy.'),
  ('fdacbb8e-2fc0-5e4e-a762-42284f8b0c6a', '8abe2c22-ce8b-520c-aa78-0a64a5c54d5b', NULL, 21, 21, 'My mouth will speak the praise of Yahweh. Let all flesh bless his holy name forever and ever.'),
  ('2b832e3f-9914-5cec-a713-682e2688cee2', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 1, 1, 'Praise Yah! Praise Yahweh, my soul.'),
  ('17de6d11-271a-5085-a9df-2d57c717c628', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 2, 2, 'While I live, I will praise Yahweh. I will sing praises to my God as long as I exist.'),
  ('e4034786-f9cd-5999-a217-9443bb726fa4', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 3, 3, 'Don''t put your trust in princes, each a son of man in whom there is no help.'),
  ('0e304e6f-6139-5cd4-ace8-9debfc65d870', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 4, 4, 'His spirit departs, and he returns to the earth. In that very day, his thoughts perish.'),
  ('c6b2708a-fbf8-57c4-aee1-41fbc34497a9', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 5, 5, 'Happy is he who has the God of Jacob for his help, whose hope is in Yahweh, his God:'),
  ('a8f433ca-62f8-5dc5-ab55-baa43f2b816d', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 6, 6, 'who made heaven and earth, the sea, and all that is in them; who keeps truth forever;'),
  ('7522c5f2-89b4-5ecf-ab11-41d7161d22aa', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 7, 7, 'who executes justice for the oppressed; who gives food to the hungry. Yahweh frees the prisoners.'),
  ('e59ddc60-c3ca-5d28-a703-e6ec17e9b866', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 8, 8, 'Yahweh opens the eyes of the blind. Yahweh raises up those who are bowed down. Yahweh loves the righteous.'),
  ('9d7c6670-06da-51c0-ab36-93dfbd866909', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 9, 9, 'Yahweh preserves the foreigners. He upholds the fatherless and widow, but the way of the wicked he turns upside down.'),
  ('54fbf41a-4437-53b3-af25-edab0f2b68cf', '97291150-c458-5722-a75b-3c47ca87caba', NULL, 10, 10, 'Yahweh will reign forever; your God, O Zion, to all generations. Praise Yah!'),
  ('919e86e7-1ea2-57e4-ada7-f83a7c3d9419', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 1, 1, 'Praise Yah, for it is good to sing praises to our God; for it is pleasant and fitting to praise him.'),
  ('caafcf6d-d8af-5bee-af26-bab8a077b838', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 2, 2, 'Yahweh builds up Jerusalem. He gathers together the outcasts of Israel.'),
  ('5b4f48f3-05fc-55e7-a071-81811c45e3b2', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 3, 3, 'He heals the broken in heart, and binds up their wounds.'),
  ('eb84ab26-6c2b-58d2-a8ce-0f31916da14f', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 4, 4, 'He counts the number of the stars. He calls them all by their names.'),
  ('e2d413b6-52d3-5c4d-a385-ece0b5353caa', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 5, 5, 'Great is our Lord, and mighty in power. His understanding is infinite.'),
  ('93a6f6d0-b612-55f7-a759-5cb4e91aac5e', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 6, 6, 'Yahweh upholds the humble. He brings the wicked down to the ground.'),
  ('2aca83e1-60cd-5987-afab-a0d5006e7557', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 7, 7, 'Sing to Yahweh with thanksgiving. Sing praises on the harp to our God,'),
  ('9961cbc3-3cdc-5e56-a504-9fbf2d43f1af', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 8, 8, 'who covers the sky with clouds, who prepares rain for the earth, who makes grass grow on the mountains.'),
  ('19910cda-0660-5644-aa44-143952bf98b0', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 9, 9, 'He provides food for the livestock, and for the young ravens when they call.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('22d53ee3-50a7-5fb7-ab7b-dee5fa585bef', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 10, 10, 'He doesn''t delight in the strength of the horse. He takes no pleasure in the legs of a man.'),
  ('3ccc63f1-78f5-58d7-a448-9a5a22119fe2', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 11, 11, 'Yahweh takes pleasure in those who fear him, in those who hope in his loving kindness.'),
  ('20bb36d6-c2b6-590d-af83-3b98399eb2f2', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 12, 12, 'Praise Yahweh, Jerusalem! Praise your God, Zion!'),
  ('9fa9fa02-579a-53db-a325-b9ea7415c32c', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 13, 13, 'For he has strengthened the bars of your gates. He has blessed your children within you.'),
  ('d0927bf1-f039-541f-a12d-172600473b89', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 14, 14, 'He makes peace in your borders. He fills you with the finest of the wheat.'),
  ('32b26b48-9a98-578a-a737-8b1078897255', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 15, 15, 'He sends out his commandment to the earth. His word runs very swiftly.'),
  ('440af4f3-c41c-5b5f-a3d8-d731abbdf562', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 16, 16, 'He gives snow like wool, and scatters frost like ashes.'),
  ('66e8f549-070c-5f1f-a7c3-7d84b19fbf9c', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 17, 17, 'He hurls down his hail like pebbles. Who can stand before his cold?'),
  ('32fdc0c7-371d-5f3c-ad4d-273c164b07f3', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 18, 18, 'He sends out his word, and melts them. He causes his wind to blow, and the waters flow.'),
  ('47fa92bb-d5b9-5793-a624-3c9dd55d7e58', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 19, 19, 'He shows his word to Jacob; his statutes and his ordinances to Israel.'),
  ('22e6f87e-3759-51e7-a7dc-5efdc72d3e7e', 'bbb8ab0d-2cfb-5459-a1e6-a637327a8771', NULL, 20, 20, 'He has not done this for just any nation. They don''t know his ordinances. Praise Yah!'),
  ('ab236cdd-e290-5954-a53e-38bb9aca62c5', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 1, 1, 'Praise Yah! Praise Yahweh from the heavens! Praise him in the heights!'),
  ('03180976-5aee-5bf0-acf0-50eb1607dd46', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 2, 2, 'Praise him, all his angels! Praise him, all his army!'),
  ('57f8b8d1-287c-5741-ae1e-91e2374bbc84', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 3, 3, 'Praise him, sun and moon! Praise him, all you shining stars!'),
  ('96871d9c-4aca-5bd4-a248-7abdb726a52e', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 4, 4, 'Praise him, you heavens of heavens, You waters that are above the heavens.'),
  ('57102188-c7e0-5c1b-a165-b94034bd5dc9', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 5, 5, 'Let them praise the name of Yahweh, For he commanded, and they were created.'),
  ('311eb12e-c70b-5fae-a70d-0156d032960f', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 6, 6, 'He has also established them forever and ever. He has made a decree which will not pass away.'),
  ('c6cbcdc1-f2a3-5782-ad94-57fd085de804', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 7, 7, 'Praise Yahweh from the earth, you great sea creatures, and all depths!'),
  ('4184300a-4e7e-59e5-a38c-53f2ba325a7b', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 8, 8, 'Lightning and hail, snow and clouds; stormy wind, fulfilling his word;'),
  ('8cc8c2ef-1301-5d8e-a773-3f12e482115a', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 9, 9, 'mountains and all hills; fruit trees and all cedars;'),
  ('46382cb5-918b-5e95-adb7-d3dccdc023f4', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 10, 10, 'wild animals and all livestock; small creatures and flying birds;'),
  ('b513b6d1-a90e-5779-a39a-802dd02b6109', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 11, 11, 'kings of the earth and all peoples; princes and all judges of the earth;'),
  ('6ebb3e86-b891-5f91-ae69-753c797c9e3f', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 12, 12, 'both young men and maidens; old men and children:'),
  ('a70c7a4e-c53b-59d2-a47a-d566454c4b14', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 13, 13, 'let them praise the name of Yahweh, for his name alone is exalted. His glory is above the earth and the heavens.'),
  ('c1f11341-f811-594e-a446-895c538c88c9', 'b6ade059-d77a-56de-aee2-fb20eb38921f', NULL, 14, 14, 'He has lifted up the horn of his people, the praise of all his saints; even of the children of Israel, a people near to him. Praise Yah!'),
  ('9fa2a8ad-a4bc-5ee1-aa8f-a0a08b0b06ae', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 1, 1, 'Praise Yahweh! Sing to Yahweh a new song, his praise in the assembly of the saints.'),
  ('bddca8ef-4be8-53e9-a586-38c302685e7e', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 2, 2, 'Let Israel rejoice in him who made them. Let the children of Zion be joyful in their King.'),
  ('4310e662-3596-5582-aaaa-7ee0f6d2b910', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 3, 3, 'Let them praise his name in the dance! Let them sing praises to him with tambourine and harp!'),
  ('4746089c-66a3-5746-aa69-7709bfc57558', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 4, 4, 'For Yahweh takes pleasure in his people. He crowns the humble with salvation.'),
  ('1686cef0-aa39-5d3d-ac40-a70b5d7b8ced', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 5, 5, 'Let the saints rejoice in honor. Let them sing for joy on their beds.'),
  ('1800332a-8675-5620-a32d-5ce0b06a38c4', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 6, 6, 'May the high praises of God be in their mouths, and a two-edged sword in their hand;'),
  ('12ce69f8-b189-57b8-a878-cedebeaad551', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 7, 7, 'To execute vengeance on the nations, and punishments on the peoples;'),
  ('86bbf096-2743-5b80-a343-6d6f6068958e', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 8, 8, 'To bind their kings with chains, and their nobles with fetters of iron;'),
  ('2c5715d2-7773-55fb-a536-ea9cafb17864', 'd5706397-b701-595a-a8ec-e31a071406a4', NULL, 9, 9, 'to execute on them the written judgment. All his saints have this honor. Praise Yah!'),
  ('3407b4a2-cc65-56c0-aa37-0a9d1f1250ba', '521d57e8-a0c9-5d67-aab8-980f4ba86461', NULL, 1, 1, 'Praise Yah! Praise God in his sanctuary! Praise him in his heavens for his acts of power!'),
  ('dc2e989a-c1cf-5622-a999-bbb44279fb15', '521d57e8-a0c9-5d67-aab8-980f4ba86461', NULL, 2, 2, 'Praise him for his mighty acts! Praise him according to his excellent greatness!'),
  ('9f49471a-d225-57a9-a4e9-303590074ae0', '521d57e8-a0c9-5d67-aab8-980f4ba86461', NULL, 3, 3, 'Praise him with the sounding of the trumpet! Praise him with harp and lyre!'),
  ('7ebd9a96-c624-5413-a689-7fb32d3f7122', '521d57e8-a0c9-5d67-aab8-980f4ba86461', NULL, 4, 4, 'Praise him with tambourine and dancing! Praise him with stringed instruments and flute!'),
  ('06a896d9-6972-5056-a271-1be2bdbea984', '521d57e8-a0c9-5d67-aab8-980f4ba86461', NULL, 5, 5, 'Praise him with loud cymbals! Praise him with resounding cymbals!'),
  ('571c2aa2-78f9-5b41-ac94-9be86f061e2f', '521d57e8-a0c9-5d67-aab8-980f4ba86461', NULL, 6, 6, 'Let everything that has breath praise Yah! Praise Yah!'),
  ('74f946bf-2bc0-5680-aebc-ad5c788ef5e6', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 1, 1, 'The proverbs of Solomon, the son of David, king of Israel:'),
  ('c19d4af8-bc1d-55b5-a3b8-83027de94be0', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 2, 2, 'to know wisdom and instruction; to discern the words of understanding;'),
  ('d68e1275-85ef-585f-ad8d-4641b0289d7d', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 3, 3, 'to receive instruction in wise dealing, in righteousness, justice, and equity;'),
  ('e5ac1bd7-ea9d-577e-aa81-23776515dfac', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 4, 4, 'to give prudence to the simple, knowledge and discretion to the young man:'),
  ('a2a7cf80-8ffa-5692-a9ca-72a718ed908b', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 5, 5, 'that the wise man may hear, and increase in learning; that the man of understanding may attain to sound counsel:'),
  ('631ee0de-d508-5238-a5a1-209c95c5da87', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 6, 6, 'to understand a proverb, and parables, the words and riddles of the wise.'),
  ('58cf608a-be43-5680-abce-5444c5eee00b', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 7, 7, 'The fear of Yahweh is the beginning of knowledge; but the foolish despise wisdom and instruction.'),
  ('9c69af79-63d8-519b-af9a-a602dbc6d176', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 8, 8, 'My son, listen to your father''s instruction, and don''t forsake your mother''s teaching:'),
  ('a9cd9f18-31e6-58ba-a5e3-0dd2e59d63b6', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 9, 9, 'for they will be a garland to grace your head, and chains around your neck.'),
  ('77667b6a-9b59-5974-a793-1fd6ae95a05b', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 10, 10, 'My son, if sinners entice you, don''t consent.'),
  ('a0c2d5b1-edda-509a-a97d-f0ca8950cefc', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 11, 11, 'If they say, "Come with us, Let''s lay in wait for blood; let''s lurk secretly for the innocent without cause;'),
  ('67dc6842-9560-509a-aabf-d95ff7622999', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 12, 12, 'let''s swallow them up alive like Sheol, and whole, like those who go down into the pit.'),
  ('0acfad51-dfb2-5091-aa1f-67ba253902b7', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 13, 13, 'We''ll find all valuable wealth. We''ll fill our houses with spoil.'),
  ('9e2d9021-f3d5-52af-acd3-1ef60440b2b5', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 14, 14, 'You shall cast your lot among us. We''ll all have one purse."'),
  ('bff4f69d-1837-5afd-ab90-c92211a62cf2', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 15, 15, 'My son, don''t walk in the way with them. Keep your foot from their path,'),
  ('847398e6-1fbd-5c1c-a092-95a18f932ff3', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 16, 16, 'for their feet run to evil. They hurry to shed blood.'),
  ('c02d28f2-b3ce-5214-aeeb-3594efd9bebe', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 17, 17, 'For in vain is the net spread in the sight of any bird:'),
  ('8fa91aa3-181f-55c0-a7f3-80a89c6fcdad', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 18, 18, 'but these lay wait for their own blood. They lurk secretly for their own lives.'),
  ('67cc7ad1-a77a-5143-ad0c-059524b28ba4', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 19, 19, 'So are the ways of everyone who is greedy for gain. It takes away the life of its owners.'),
  ('7c74076b-b2b8-59d2-a00c-b7ef394c5733', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 20, 20, 'Wisdom calls aloud in the street. She utters her voice in the public squares.'),
  ('9da8bc1c-87a1-5869-aa69-ec72eefdff6f', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 21, 21, 'She calls at the head of noisy places. At the entrance of the city gates, she utters her words:'),
  ('63e0f48c-46f1-51b7-a9ab-92a0713d62ee', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 22, 22, '"How long, you simple ones, will you love simplicity? How long will mockers delight themselves in mockery, and fools hate knowledge?'),
  ('fbaaed63-b8b2-59f3-ac7f-1d82ec03c3f2', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 23, 23, 'Turn at my reproof. Behold, I will pour out my spirit on you. I will make known my words to you.'),
  ('e079208f-2098-5cdf-a069-5fa5d83aabbe', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 24, 24, 'Because I have called, and you have refused; I have stretched out my hand, and no one has paid attention;'),
  ('266ef49d-f529-5086-a715-8c1982ace9dc', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 25, 25, 'but you have ignored all my counsel, and wanted none of my reproof;'),
  ('7096f47c-3980-529a-aa89-169766444c02', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 26, 26, 'I also will laugh at your disaster. I will mock when calamity overtakes you;'),
  ('c3aad958-d1e7-518c-a3ac-ece123e1ae3c', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 27, 27, 'when calamity overtakes you like a storm, when your disaster comes on like a whirlwind; when distress and anguish come on you.'),
  ('4afbf896-ea64-5160-a4be-75fc077958c7', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 28, 28, 'Then will they call on me, but I will not answer. They will seek me diligently, but they will not find me;'),
  ('467cec45-8cea-59e9-a661-662fc5543110', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 29, 29, 'because they hated knowledge, and didn''t choose the fear of Yahweh.'),
  ('75f9243c-ba6a-5612-ae72-ff6566a6b3c2', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 30, 30, 'They wanted none of my counsel. They despised all my reproof.'),
  ('0233220b-327c-5a1d-a4a0-c533018d4d62', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 31, 31, 'Therefore they will eat of the fruit of their own way, and be filled with their own schemes.'),
  ('c3781675-1f6d-5b34-a65b-fd523173317b', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 32, 32, 'For the backsliding of the simple will kill them. The careless ease of fools will destroy them.'),
  ('42d4dcda-6bee-55b6-a63b-7103516a2792', '8b8e93e2-c20f-5b3e-aaaf-0b13e0a018fa', NULL, 33, 33, 'But whoever listens to me will dwell securely, and will be at ease, without fear of harm."'),
  ('874fbeb2-b595-5d68-a4d2-bb8c15bed511', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 1, 1, 'My son, if you will receive my words, and store up my commandments within you;'),
  ('a1cbeecf-9852-5692-a64d-95cd555fd1d1', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 2, 2, 'So as to turn your ear to wisdom, and apply your heart to understanding;'),
  ('7fae2448-cec5-5785-a8da-c4521bc8c61c', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 3, 3, 'Yes, if you call out for discernment, and lift up your voice for understanding;'),
  ('c82feae9-da20-5b86-a161-afee26ce2f63', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 4, 4, 'If you seek her as silver, and search for her as for hidden treasures:'),
  ('38f30fdb-37bf-5226-a0cc-5efde82a6173', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 5, 5, 'then you will understand the fear of Yahweh, and find the knowledge of God.'),
  ('a6fd14ce-8325-5e27-a7cf-3f9e85359f82', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 6, 6, 'For Yahweh gives wisdom. Out of his mouth comes knowledge and understanding.'),
  ('e248e72b-cfd0-5dc5-ae18-4adecd61faa8', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 7, 7, 'He lays up sound wisdom for the upright. He is a shield to those who walk in integrity;'),
  ('298d80e7-f25d-5482-afe3-2f7c6005ab52', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 8, 8, 'that he may guard the paths of justice, and preserve the way of his saints.'),
  ('222ec10c-414a-565a-a073-bebec07921c7', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 9, 9, 'Then you will understand righteousness and justice, equity and every good path.'),
  ('8fecba17-0250-518f-a9cc-70aa3ca65782', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 10, 10, 'For wisdom will enter into your heart. Knowledge will be pleasant to your soul.'),
  ('681fd7b3-21bf-5a0d-ae80-431e8ffa2838', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 11, 11, 'Discretion will watch over you. Understanding will keep you,'),
  ('0f86d63d-b9da-5bef-a4e1-d2f408701b49', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 12, 12, 'to deliver you from the way of evil, from the men who speak perverse things;'),
  ('4e14e91e-4490-5472-a287-8940b6e9343e', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 13, 13, 'who forsake the paths of uprightness, to walk in the ways of darkness;'),
  ('c97aa436-ed36-5a5b-adce-e24654c8a27e', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 14, 14, 'who rejoice to do evil, and delight in the perverseness of evil;'),
  ('db755903-9e9e-5c96-aebb-4c4ce46c9549', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 15, 15, 'who are crooked in their ways, and wayward in their paths:'),
  ('4db80a2d-d7a0-5d60-a8e6-659c0fbba9fa', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 16, 16, 'To deliver you from the strange woman, even from the foreigner who flatters with her words;'),
  ('4368395b-8c3c-5fdd-a478-c8a957138441', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 17, 17, 'who forsakes the friend of her youth, and forgets the covenant of her God:'),
  ('3408c3fa-2e27-53e9-a92a-19adc584404c', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 18, 18, 'for her house leads down to death, her paths to the dead.'),
  ('436f18c8-e549-573d-a005-bc1d27ecdad3', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 19, 19, 'None who go to her return again, neither do they attain to the paths of life:'),
  ('575d66c3-cb9b-55d1-a48a-71bd91638977', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 20, 20, 'that you may walk in the way of good men, and keep the paths of the righteous.'),
  ('2ff20a74-df46-5c6c-a19f-cf025aaa82aa', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 21, 21, 'For the upright will dwell in the land. The perfect will remain in it.'),
  ('c37ff7ae-7b59-50bc-ae59-ae64de2dd08d', '8a72cbc3-a950-5032-a627-aede12595f63', NULL, 22, 22, 'But the wicked will be cut off from the land. The treacherous will be rooted out of it.'),
  ('4f4c9e86-3438-567b-aefb-494d614c7734', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 1, 1, 'My son, don''t forget my teaching; but let your heart keep my commandments:'),
  ('8fa9b7d2-b83f-5c6f-a75c-e2ac856eb696', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 2, 2, 'for length of days, and years of life, and peace, will they add to you.'),
  ('c706fab5-a3bb-5b1b-af4d-766b84280208', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 3, 3, 'Don''t let kindness and truth forsake you. Bind them around your neck. Write them on the tablet of your heart.'),
  ('84d7cd91-0466-5232-af3a-7e0556c51f6e', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 4, 4, 'So you will find favor, and good understanding in the sight of God and man.'),
  ('eef7c481-272d-5b57-af00-c1eb34c07089', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 5, 5, 'Trust in Yahweh with all your heart, and don''t lean on your own understanding.'),
  ('ea86ee7e-662e-55ff-a473-9aa8e036bcb8', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 6, 6, 'In all your ways acknowledge him, and he will make your paths straight.'),
  ('88a51940-db69-5dd2-a27e-09bde715d5b2', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 7, 7, 'Don''t be wise in your own eyes. Fear Yahweh, and depart from evil.'),
  ('336f1101-c664-5d45-abb4-e144de4d8998', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 8, 8, 'It will be health to your body, and nourishment to your bones.'),
  ('ec12b3a5-3902-55db-afd8-3e356773bf72', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 9, 9, 'Honor Yahweh with your substance, with the first fruits of all your increase:'),
  ('5dc3d8eb-3912-5238-ad2c-dd7b58244bb1', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 10, 10, 'so your barns will be filled with plenty, and your vats will overflow with new wine.'),
  ('5d8decda-a865-55ee-aaf4-2a91cac69a02', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 11, 11, 'My son, don''t despise Yahweh''s discipline, neither be weary of his reproof:'),
  ('5e4eec08-eced-5ebb-af98-067c51688ce3', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 12, 12, 'for whom Yahweh loves, he reproves; even as a father reproves the son in whom he delights.'),
  ('25208d1a-65a3-54ad-acec-9726f3aca3ca', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 13, 13, 'Happy is the man who finds wisdom, the man who gets understanding.'),
  ('39808002-ec59-56ec-a96d-d099674e7e1d', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 14, 14, 'For her good profit is better than getting silver, and her return is better than fine gold.'),
  ('cec59e4d-b6ec-5f46-a029-4784bf6934ec', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 15, 15, 'She is more precious than rubies. None of the things you can desire are to be compared to her.'),
  ('aec115ee-bdd0-5888-a96a-edc88c3dff47', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 16, 16, 'Length of days is in her right hand. In her left hand are riches and honor.'),
  ('a02477fc-b41f-52eb-af74-79e7172f8e99', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 17, 17, 'Her ways are ways of pleasantness. All her paths are peace.'),
  ('c15d3327-4ddc-5ff2-a544-d799ed8e88d5', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 18, 18, 'She is a tree of life to those who lay hold of her. Happy is everyone who retains her.'),
  ('f40e5b7d-c75b-5bdc-ac87-cc1fae9c606e', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 19, 19, 'By wisdom Yahweh founded the earth. By understanding, he established the heavens.'),
  ('b9cfff21-b8a6-5a3c-a10c-cf2d8cf619bb', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 20, 20, 'By his knowledge, the depths were broken up, and the skies drop down the dew.'),
  ('ac4cc0cf-e616-5f74-a33c-fe249154e060', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 21, 21, 'My son, let them not depart from your eyes. Keep sound wisdom and discretion:'),
  ('760447c7-fd43-57f2-ad72-822cca360ebc', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 22, 22, 'so they will be life to your soul, and grace for your neck.'),
  ('cc605d43-46f9-5161-ade3-6de31968f977', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 23, 23, 'Then you shall walk in your way securely. Your foot won''t stumble.'),
  ('f83b3fa6-2b08-5730-a3a6-31da503d30be', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 24, 24, 'When you lie down, you will not be afraid. Yes, you will lie down, and your sleep will be sweet.'),
  ('e406f1d1-bda8-5353-ae1a-d42081d5f88c', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 25, 25, 'Don''t be afraid of sudden fear, neither of the desolation of the wicked, when it comes:'),
  ('df716735-1d90-529f-adfb-f1db3e2d2967', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 26, 26, 'for Yahweh will be your confidence, and will keep your foot from being taken.'),
  ('07e7513b-e4e4-5b1a-a7fc-7730698b60e0', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 27, 27, 'Don''t withhold good from those to whom it is due, when it is in the power of your hand to do it.'),
  ('7f6c971a-6247-52fe-a251-e3048fa3356e', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 28, 28, 'Don''t say to your neighbor, "Go, and come again; tomorrow I will give it to you," when you have it by you.'),
  ('11fb7126-bfdb-54f8-a307-988c17b391cd', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 29, 29, 'Don''t devise evil against your neighbor, since he dwells securely by you.'),
  ('944edf12-9d86-5ff0-a073-6d6bfd07ad93', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 30, 30, 'Don''t strive with a man without cause, if he has done you no harm.'),
  ('4ed9de76-ee45-5470-a677-a2d45bc5d9ac', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 31, 31, 'Don''t envy the man of violence. Choose none of his ways.'),
  ('b3358498-2316-54c0-a4eb-1f5f66ffc7e0', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 32, 32, 'For the perverse is an abomination to Yahweh, but his friendship is with the upright.'),
  ('2cf4209a-fa25-5ca0-a46d-ef59ac837b0c', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 33, 33, 'Yahweh''s curse is in the house of the wicked, but he blesses the habitation of the righteous.'),
  ('5e6dd8bd-00a1-5f94-a044-5e800854f718', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 34, 34, 'Surely he mocks the mockers, but he gives grace to the humble.'),
  ('907a5999-fac1-521b-ab73-a943f83f58fb', '766f1376-208a-552d-a9eb-7b84934b694f', NULL, 35, 35, 'The wise will inherit glory, but shame will be the promotion of fools.'),
  ('f1c359bc-1d11-5bc9-a7e0-366a8704fb06', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 1, 1, 'Listen, sons, to a father''s instruction. Pay attention and know understanding;'),
  ('4fa594c8-ea89-52ab-a450-78559865673f', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 2, 2, 'for I give you sound learning. Don''t forsake my law.'),
  ('4f115394-e01d-51b2-ae3d-46cf7e41cf6b', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 3, 3, 'For I was a son to my father, tender and an only child in the sight of my mother.'),
  ('cdcd3b3a-2818-5e1d-a620-9da80a207659', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 4, 4, 'He taught me, and said to me: "Let your heart retain my words. Keep my commandments, and live.'),
  ('ea5187f9-d45a-5d49-af8a-c4fe228e8aa2', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 5, 5, 'Get wisdom. Get understanding. Don''t forget, neither swerve from the words of my mouth.'),
  ('ba5438d4-8d92-55da-ad25-4c43335da409', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 6, 6, 'Don''t forsake her, and she will preserve you. Love her, and she will keep you.'),
  ('407ff9f7-ee9e-5fa7-a8b2-6badb4bf24af', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 7, 7, 'Wisdom is supreme. Get wisdom. Yes, though it costs all your possessions, get understanding.'),
  ('054d854d-d397-5a35-aa4a-7aac201cf83f', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 8, 8, 'Esteem her, and she will exalt you. She will bring you to honor, when you embrace her.'),
  ('ab57db35-fcef-5701-a6a4-99dcb03a5936', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 9, 9, 'She will give to your head a garland of grace. She will deliver a crown of splendor to you."'),
  ('0ebbae2a-9f11-5ab7-a765-140a3139925c', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 10, 10, 'Listen, my son, and receive my sayings. The years of your life will be many.'),
  ('34f40384-2483-523f-a2c6-b92854a091d6', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 11, 11, 'I have taught you in the way of wisdom. I have led you in straight paths.'),
  ('c4b1aea3-ad1e-5331-a14f-4b8c3ba4c48e', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 12, 12, 'When you go, your steps will not be hampered. When you run, you will not stumble.'),
  ('6f92d846-1b7c-5b49-a6d6-892379add4cb', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 13, 13, 'Take firm hold of instruction. Don''t let her go. Keep her, for she is your life.'),
  ('258ff7f8-11c3-586b-ade1-4a2f93274bf4', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 14, 14, 'Don''t enter into the path of the wicked. Don''t walk in the way of evil men.'),
  ('0e951ea8-8006-5c85-abbf-ef74fa4f13ac', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 15, 15, 'Avoid it, and don''t pass by it. Turn from it, and pass on.'),
  ('15e49e85-c93d-58a8-aa04-562478ed567a', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 16, 16, 'For they don''t sleep, unless they do evil. Their sleep is taken away, unless they make someone fall.'),
  ('6741745c-d20e-54cb-ac11-849aaffcfa57', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 17, 17, 'For they eat the bread of wickedness, and drink the wine of violence.'),
  ('450426bd-ba25-59ac-ac07-1cde4bfe5d9e', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 18, 18, 'But the path of the righteous is like the dawning light, that shines more and more until the perfect day.'),
  ('8c141681-b4db-568a-ae95-49f973821b00', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 19, 19, 'The way of the wicked is like darkness. They don''t know what they stumble over.'),
  ('78917856-d69d-50fc-ab3a-1ff3a12ec378', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 20, 20, 'My son, attend to my words. Turn your ear to my sayings.'),
  ('e9a950a7-6fab-5c3a-ab00-01edd9aef366', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 21, 21, 'Let them not depart from your eyes. Keep them in the midst of your heart.'),
  ('c01ff40b-42f0-56c2-ab9d-535a3222c316', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 22, 22, 'For they are life to those who find them, and health to their whole body.'),
  ('66f5a7a8-cc9b-5a94-a323-a093bb248257', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 23, 23, 'Keep your heart with all diligence, for out of it is the wellspring of life.'),
  ('fe4bb65a-7c13-588a-ad31-7302aa3bcba1', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 24, 24, 'Put away from yourself a perverse mouth. Put corrupt lips far from you.'),
  ('5981a279-b9a2-569b-ab89-79fb4cb29d26', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 25, 25, 'Let your eyes look straight ahead. Fix your gaze directly before you.'),
  ('583ccf9a-839a-5f4f-ab3e-e6889504957a', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 26, 26, 'Make the path of your feet level. Let all of your ways be established.'),
  ('ca767f5b-dc99-5f2f-ac11-65320d5417cb', 'f3df6732-0794-5809-ab6d-bc8173d77306', NULL, 27, 27, 'Don''t turn to the right hand nor to the left. Remove your foot from evil.'),
  ('525853cb-7d16-55a2-a442-9c16b613e26c', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 1, 1, 'My son, pay attention to my wisdom. Turn your ear to my understanding:'),
  ('c3598d22-b4f0-5e51-a21c-f8d1c9c3d771', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 2, 2, 'that you may maintain discretion, that your lips may preserve knowledge.'),
  ('673f6578-b22d-5e3c-a5bf-fb0f359283bb', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 3, 3, 'For the lips of an adulteress drip honey. Her mouth is smoother than oil,'),
  ('41421c23-8766-58d8-adb9-73316a43e967', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 4, 4, 'But in the end she is as bitter as wormwood, and as sharp as a two-edged sword.'),
  ('e0e504de-8bf8-5b50-a509-7b28ca726cb7', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 5, 5, 'Her feet go down to death. Her steps lead straight to Sheol.'),
  ('588ce05e-7866-53d3-a037-801b1964c78b', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 6, 6, 'She gives no thought to the way of life. Her ways are crooked, and she doesn''t know it.'),
  ('a66a521a-0159-5438-a542-6459b15a999e', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 7, 7, 'Now therefore, my sons, listen to me. Don''t depart from the words of my mouth.'),
  ('97be3dd1-23b3-5c1e-ae8e-cf31edfbe863', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 8, 8, 'Remove your way far from her. Don''t come near the door of her house,'),
  ('00b0e1f8-dc5d-50e7-aaea-9ebe20ac0bcc', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 9, 9, 'lest you give your honor to others, and your years to the cruel one;'),
  ('3bf82c4b-cdf9-5e37-a37b-2849dec61e2c', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 10, 10, 'lest strangers feast on your wealth, and your labors enrich another man''s house.'),
  ('9c8b51a7-e153-5c50-a8af-293f7e884e80', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 11, 11, 'You will groan at your latter end, when your flesh and your body are consumed,'),
  ('916196da-b5be-51f9-a009-84c59e789da7', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 12, 12, 'and say, "How I have hated instruction, and my heart despised reproof;'),
  ('35f7a2a4-e3da-5ea1-ab5c-5fb74ddf37cb', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 13, 13, 'neither have I obeyed the voice of my teachers, nor turned my ear to those who instructed me!'),
  ('fa763ef9-4baa-5b5f-aee6-1c2aa4621200', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 14, 14, 'I have come to the brink of utter ruin, in the midst of the gathered assembly."'),
  ('121f4982-6bee-550d-ab74-d479e94d60d2', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 15, 15, 'Drink water out of your own cistern, running water out of your own well.'),
  ('90c59608-5594-5dc3-ae84-278bbfbb15df', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 16, 16, 'Should your springs overflow in the streets, streams of water in the public squares?'),
  ('ffda2535-6ed7-5695-a95e-c1cf20d594a4', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 17, 17, 'Let them be for yourself alone, not for strangers with you.'),
  ('c684795f-7d17-52f1-af80-d766d9a90366', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 18, 18, 'Let your spring be blessed. Rejoice in the wife of your youth.'),
  ('25e76a05-7b38-55b8-a6a4-7408bbafe7e1', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 19, 19, 'A loving doe and a graceful deer-- let her breasts satisfy you at all times. Be captivated always with her love.'),
  ('9b6bb201-b3be-51d8-a006-0fbc78383f77', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 20, 20, 'For why should you, my son, be captivated with an adulteress? Why embrace the bosom of another?'),
  ('509457dd-2187-558e-a462-bbf6609dfce1', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 21, 21, 'For the ways of man are before the eyes of Yahweh. He examines all his paths.'),
  ('379d6485-a072-5c59-a0b3-dc1c411f5e22', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 22, 22, 'The evil deeds of the wicked ensnare him. The cords of his sin hold him firmly.'),
  ('a47328f3-b1d8-547e-ae25-0f8e665e418f', '70e6ccf5-6c77-5c9a-aeac-8f05d3ad951e', NULL, 23, 23, 'He will die for lack of instruction. In the greatness of his folly, he will go astray.'),
  ('858723db-4656-50ff-af14-0507b02f967e', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 1, 1, 'My son, if you have become collateral for your neighbor, if you have struck your hands in pledge for a stranger;'),
  ('d6021d32-dcd6-58cf-a22b-9dd73681fcee', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 2, 2, 'You are trapped by the words of your mouth. You are ensnared with the words of your mouth.'),
  ('98540fa4-2e9c-535a-af32-7fdf664f5823', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 3, 3, 'Do this now, my son, and deliver yourself, since you have come into the hand of your neighbor. Go, humble yourself. Press your plea with your neighbor.'),
  ('1ec9f9db-1820-5380-a053-6c979dd69666', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 4, 4, 'Give no sleep to your eyes, nor slumber to your eyelids.'),
  ('9fb8e0d0-8412-5a19-ae2f-0353a2370f8d', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 5, 5, 'Free yourself, like a gazelle from the hand of the hunter, like a bird from the snare of the fowler.'),
  ('d662d6fb-d908-5886-a79a-788a5f428b66', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 6, 6, 'Go to the ant, you sluggard. Consider her ways, and be wise;'),
  ('99e5d57d-9c0b-5f19-aed7-aa674f7b60f7', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 7, 7, 'which having no chief, overseer, or ruler,'),
  ('a882f42d-1cd2-5c6f-a070-66e8109f7ac7', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 8, 8, 'provides her bread in the summer, and gathers her food in the harvest.'),
  ('3dada5c2-c03f-5015-af0b-81be70bfbf8a', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 9, 9, 'How long will you sleep, sluggard? When will you arise out of your sleep?'),
  ('a7b819b9-e238-5bf7-a62a-26a76126eaaa', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 10, 10, 'A little sleep, a little slumber, a little folding of the hands to sleep:'),
  ('fc2fbcb5-af6c-5579-a93a-b526356959ee', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 11, 11, 'so your poverty will come as a robber, and your scarcity as an armed man.'),
  ('3d705d5a-4f93-5a0e-aa63-6abe5404a868', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 12, 12, 'A worthless person, a man of iniquity, is he who walks with a perverse mouth;'),
  ('25d7de19-d650-565c-ad3f-73227ec2c174', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 13, 13, 'who winks with his eyes, who signals with his feet, who motions with his fingers;'),
  ('239433d2-3682-522d-a5e1-bbda7ea24bf1', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 14, 14, 'in whose heart is perverseness, who devises evil continually, who always sows discord.'),
  ('c4917252-426f-573e-a165-641c74d81dde', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 15, 15, 'Therefore his calamity will come suddenly. He will be broken suddenly, and that without remedy.'),
  ('b01a5530-556d-5c2b-a97e-6a651325181e', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 16, 16, 'There are six things which Yahweh hates; yes, seven which are an abomination to him:'),
  ('b42da206-44eb-5240-ae90-02ef21af3183', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 17, 17, 'haughty eyes, a lying tongue, hands that shed innocent blood;'),
  ('43537ef9-6cd3-5b21-ace4-45cb157709ee', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 18, 18, 'a heart that devises wicked schemes, feet that are swift in running to mischief,'),
  ('bd8f4faf-5ff7-533d-aa64-63789ea9e1c4', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 19, 19, 'a false witness who utters lies, and he who sows discord among brothers.'),
  ('438f2c98-f1c4-5ad9-a12d-c5f1ad3d82d9', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 20, 20, 'My son, keep your father''s commandment, and don''t forsake your mother''s teaching.'),
  ('fd438e9c-f18d-52a9-a885-855526349c15', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 21, 21, 'Bind them continually on your heart. Tie them around your neck.'),
  ('0ae04d88-4dfe-5a11-aee1-e6a0b1ab4cbf', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 22, 22, 'When you walk, it will lead you. When you sleep, it will watch over you. When you awake, it will talk with you.'),
  ('7ebbb729-6862-5ce9-ac8c-9bed68289676', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 23, 23, 'For the commandment is a lamp, and the law is light. Reproofs of instruction are the way of life,'),
  ('bee72428-dcba-56ec-aaf6-60729740613a', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 24, 24, 'to keep you from the immoral woman, from the flattery of the wayward wife''s tongue.'),
  ('95ef51e2-f8ed-5963-ac3f-53e5e6c5a127', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 25, 25, 'Don''t lust after her beauty in your heart, neither let her captivate you with her eyelids.'),
  ('460b7e16-ef7d-5500-a496-7606fd3c376c', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 26, 26, 'For a prostitute reduces you to a piece of bread. The adulteress hunts for your precious life.'),
  ('fe05e800-df6a-5149-a11b-028da8d4563d', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 27, 27, 'Can a man scoop fire into his lap, and his clothes not be burned?'),
  ('2e2e84ce-2934-5b9e-ad6f-41a8a9df9d05', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 28, 28, 'Or can one walk on hot coals, and his feet not be scorched?'),
  ('5bcdb96e-83f0-59e2-af8e-c91f9aacd3ce', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 29, 29, 'So is he who goes in to his neighbor''s wife. Whoever touches her will not be unpunished.'),
  ('e77f1f72-4dfa-5ed0-a46d-ddaecc459103', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 30, 30, 'Men don''t despise a thief, if he steals to satisfy himself when he is hungry:'),
  ('25987217-d39b-5069-a737-b97fca3d9800', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 31, 31, 'but if he is found, he shall restore seven times. He shall give all the wealth of his house.'),
  ('e3ff1d2a-fcd0-516d-ab62-90b9b5217de4', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 32, 32, 'He who commits adultery with a woman is void of understanding. He who does it destroys his own soul.'),
  ('4fa3ea58-df08-5caf-afae-0a6325d683d7', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 33, 33, 'He will get wounds and dishonor. His reproach will not be wiped away.'),
  ('f3e2cd5d-6202-5aae-a3f1-0736949d0e9d', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 34, 34, 'For jealousy arouses the fury of the husband. He won''t spare in the day of vengeance.'),
  ('a0ebf1c1-afe9-50e9-aa74-abd3dd38df41', '61637d61-9745-5089-a9df-3b81dd823f4c', NULL, 35, 35, 'He won''t regard any ransom, neither will he rest content, though you give many gifts.'),
  ('ce782b21-bb92-5236-a754-3bcd60b645ce', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 1, 1, 'My son, keep my words. Lay up my commandments within you.'),
  ('3713986f-51e0-55ad-a8ea-09c301a8adc4', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 2, 2, 'Keep my commandments and live! Guard my teaching as the apple of your eye.'),
  ('4bd7d3e3-8370-532a-a215-fee4a9457cc4', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 3, 3, 'Bind them on your fingers. Write them on the tablet of your heart.'),
  ('399f03e9-3f4f-5760-aed9-4067151c6ef1', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 4, 4, 'Tell wisdom, "You are my sister." Call understanding your relative,'),
  ('e07f8fd0-e6b2-56c7-a554-9fc5bf61921d', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 5, 5, 'that they may keep you from the strange woman, from the foreigner who flatters with her words.'),
  ('788be66e-c81d-511a-a089-391a47d61319', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 6, 6, 'For at the window of my house, I looked out through my lattice.'),
  ('678f93b6-6083-5667-a8f8-5198f85b1af2', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 7, 7, 'I saw among the simple ones. I discerned among the youths a young man void of understanding,'),
  ('98087492-2a95-52d5-ae9b-9271ab1832b2', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 8, 8, 'passing through the street near her corner, he went the way to her house,'),
  ('2e23ff14-1b86-54e0-a27d-f2573e39134e', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 9, 9, 'in the twilight, in the evening of the day, in the middle of the night and in the darkness.'),
  ('3028860d-2c32-57c6-a5f8-6c108ebdecaf', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 10, 10, 'Behold, there a woman met him with the attire of a prostitute, and with crafty intent.'),
  ('6409b4ea-fe4a-5a07-a343-8ae9fa2778c1', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 11, 11, 'She is loud and defiant. Her feet don''t stay in her house.'),
  ('fcfd8097-d2d2-5ada-aaeb-6dafba1f8d23', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 12, 12, 'Now she is in the streets, now in the squares, and lurking at every corner.'),
  ('2c2902c0-681c-52ec-af56-5c96ffc1173c', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 13, 13, 'So she caught him, and kissed him. With an impudent face she said to him:'),
  ('8a1f8032-62cd-5f07-a963-20c0dde98032', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 14, 14, '"Sacrifices of peace offerings are with me. This day I have paid my vows.'),
  ('9681ba63-658d-5796-a5e8-ed7e51a240b7', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 15, 15, 'Therefore I came out to meet you, to diligently seek your face, and I have found you.'),
  ('ce628090-9d51-5172-ad61-b19ba997175c', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 16, 16, 'I have spread my couch with carpets of tapestry, with striped cloths of the yarn of Egypt.'),
  ('2a39df48-1cfd-515c-a4c9-58ddb9534386', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 17, 17, 'I have perfumed my bed with myrrh, aloes, and cinnamon.'),
  ('f8c8f702-a81b-504b-a775-14d899effe1e', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 18, 18, 'Come, let''s take our fill of loving until the morning. Let''s solace ourselves with loving.'),
  ('99056cc3-c531-585b-a43b-a1bea17f8bc5', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 19, 19, 'For my husband isn''t at home. He has gone on a long journey.'),
  ('e8465ac8-9fb6-5022-ae83-2eb69f4b66a0', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 20, 20, 'He has taken a bag of money with him. He will come home at the full moon."'),
  ('0e2e5148-cc38-5828-ac29-4d47009327af', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 21, 21, 'With persuasive words, she led him astray. With the flattering of her lips, she seduced him.'),
  ('bd89c771-7a29-50b7-a405-5bfb4f4899e3', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 22, 22, 'He followed her immediately, as an ox goes to the slaughter, as a fool stepping into a noose.'),
  ('a10da1e9-615e-5f16-a59f-825dcac86d7b', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 23, 23, 'Until an arrow strikes through his liver, as a bird hurries to the snare, and doesn''t know that it will cost his life.'),
  ('bb5598d2-1cfb-5182-a3b7-0f166e721d27', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 24, 24, 'Now therefore, sons, listen to me. Pay attention to the words of my mouth.'),
  ('31442464-5224-538e-ab0d-e6d77192d30a', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 25, 25, 'Don''t let your heart turn to her ways. Don''t go astray in her paths,'),
  ('bf8a990c-ac2d-5c51-a8e1-0687601c2f1b', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 26, 26, 'for she has thrown down many wounded. Yes, all her slain are a mighty army.'),
  ('ac3992e8-4e50-5a71-ad4f-9e510f743cf2', 'abd86f2e-1865-5f4e-a161-4933508f7ad6', NULL, 27, 27, 'Her house is the way to Sheol, going down to the rooms of death.'),
  ('acbac488-34c3-59d5-a8c4-d49f64058c11', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 1, 1, 'Doesn''t wisdom cry out? Doesn''t understanding raise her voice?'),
  ('872634a1-c2c6-5a47-a1f2-11890b534067', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 2, 2, 'On the top of high places by the way, where the paths meet, she stands.'),
  ('83f2aab2-061e-50ff-a036-cd8802922452', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 3, 3, 'Beside the gates, at the entry of the city, at the entry doors, she cries aloud:'),
  ('2cb84e8e-b203-5d71-a10f-830c42ac384e', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 4, 4, '"To you men, I call! I send my voice to the sons of mankind.'),
  ('9831f555-e11c-51fe-a50b-47441f676806', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 5, 5, 'You simple, understand prudence. You fools, be of an understanding heart.'),
  ('3f9e71ad-636f-50b4-aff6-7bdf97963eb6', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 6, 6, 'Hear, for I will speak excellent things. The opening of my lips is for right things.'),
  ('74058da5-22d2-5a26-a201-1f08241a3139', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 7, 7, 'For my mouth speaks truth. Wickedness is an abomination to my lips.'),
  ('3a1bb806-ce51-5cd5-a285-108c56861c84', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 8, 8, 'All the words of my mouth are in righteousness. There is nothing crooked or perverse in them.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('36dd4ece-687b-5918-a4a4-aa07fe482434', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 9, 9, 'They are all plain to him who understands, right to those who find knowledge.'),
  ('e81784cd-4dd2-5a12-af93-1405b20fe01e', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 10, 10, 'Receive my instruction rather than silver; knowledge rather than choice gold.'),
  ('1f90d395-cb6f-576a-a00a-a5a7a2a73c3e', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 11, 11, 'For wisdom is better than rubies. All the things that may be desired can''t be compared to it.'),
  ('eca61a2e-ac5d-53dd-ad2a-12312c0bee38', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 12, 12, '"I, wisdom, have made prudence my dwelling. Find out knowledge and discretion.'),
  ('b2613e46-d413-5c69-a4f1-6ebb45c6004e', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 13, 13, 'The fear of Yahweh is to hate evil. I hate pride, arrogance, the evil way, and the perverse mouth.'),
  ('619352d9-fc8c-5fdd-a3ac-ae2540df3350', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 14, 14, 'Counsel and sound knowledge are mine. I have understanding and power.'),
  ('4ebd63ba-8c4e-5438-a3b6-b109ad11483e', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 15, 15, 'By me kings reign, and princes decree justice.'),
  ('088e7525-3ba7-5215-a22e-4c2d0090db0f', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 16, 16, 'By me princes rule; nobles, and all the righteous rulers of the earth.'),
  ('99a15995-9bdd-5348-ad08-fc8af87cf209', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 17, 17, 'I love those who love me. Those who seek me diligently will find me.'),
  ('d19b3d41-d00f-57a6-ac35-b1eda4efdaa3', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 18, 18, 'With me are riches, honor, enduring wealth, and prosperity.'),
  ('a5e9897b-7d35-511d-a9fb-55ef5cd4f845', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 19, 19, 'My fruit is better than gold, yes, than fine gold; my yield than choice silver.'),
  ('6627a96b-a9d9-5857-a84f-df8c41e59f13', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 20, 20, 'I walk in the way of righteousness, in the midst of the paths of justice;'),
  ('ef8b2166-ee47-539a-a078-ca3c8391611b', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 21, 21, 'That I may give wealth to those who love me. I fill their treasuries.'),
  ('12d3f747-d373-53c0-a37c-211acb5c521c', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 22, 22, '"Yahweh possessed me in the beginning of his work, before his deeds of old.'),
  ('41c331a6-5930-5eff-aa64-51a53a371e49', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 23, 23, 'I was set up from everlasting, from the beginning, before the earth existed.'),
  ('e511161c-e803-59cb-af3d-35624d33fbc0', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 24, 24, 'When there were no depths, I was brought forth, when there were no springs abounding with water.'),
  ('6cf37b34-be25-571f-a2d4-004e8385f292', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 25, 25, 'Before the mountains were settled in place, before the hills, I was brought forth;'),
  ('7aa8c5bb-c52e-5a56-a98d-6564098a337f', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 26, 26, 'while as yet he had not made the earth, nor the fields, nor the beginning of the dust of the world.'),
  ('1958da81-a835-574a-a64b-24eab8ca5007', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 27, 27, 'When he established the heavens, I was there; when he set a circle on the surface of the deep,'),
  ('71f37310-baf0-554c-ad6c-b0613b124f62', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 28, 28, 'when he established the clouds above, when the springs of the deep became strong,'),
  ('e8b1f6e0-132c-50ab-a6f9-359b5e62cd3c', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 29, 29, 'when he gave to the sea its boundary, that the waters should not violate his commandment, when he marked out the foundations of the earth;'),
  ('5b88bedb-24ea-52f7-ab3b-c3a337312a7d', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 30, 30, 'then I was the craftsman by his side. I was a delight day by day, always rejoicing before him,'),
  ('3fe46aa9-1f34-5044-a08c-58ddfc735d20', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 31, 31, 'Rejoicing in his whole world. My delight was with the sons of men.'),
  ('9afa3cca-0349-54dd-a20b-f391bc184c50', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 32, 32, '"Now therefore, my sons, listen to me, for blessed are those who keep my ways.'),
  ('092fc424-608f-53a9-a22e-863b7b3cc429', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 33, 33, 'Hear instruction, and be wise. Don''t refuse it.'),
  ('72284d30-1f00-52e4-a062-805e7692ac3a', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 34, 34, 'Blessed is the man who hears me, watching daily at my gates, waiting at my door posts.'),
  ('0b9d6e5a-e857-5b3d-a557-1078ca5fa8ee', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 35, 35, 'For whoever finds me, finds life, and will obtain favor from Yahweh.'),
  ('2fa36fd5-5d52-5293-ac69-962d9bd802ac', '58c0e7c0-ef54-5ab1-a2c6-d8ef8f5bd2f1', NULL, 36, 36, 'But he who sins against me wrongs his own soul. All those who hate me love death."'),
  ('449d40a9-d2a5-5cbd-a20c-a8c08163f011', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 1, 1, 'Wisdom has built her house. She has carved out her seven pillars.'),
  ('98bea6ab-0f40-5d60-ac48-91af19349af5', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 2, 2, 'She has prepared her meat. She has mixed her wine. She has also set her table.'),
  ('b1ffed22-d754-577a-a3bd-aaf9a7930057', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 3, 3, 'She has sent out her maidens. She cries from the highest places of the city:'),
  ('e421e07b-de73-5556-a0d5-703d247e61a2', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 4, 4, '"Whoever is simple, let him turn in here!" As for him who is void of understanding, she says to him,'),
  ('0b7e553f-a5c2-552a-a046-febc8c76ed44', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 5, 5, '"Come, eat some of my bread, Drink some of the wine which I have mixed!'),
  ('85b99431-0646-5af8-a2c3-ab4195389a7a', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 6, 6, 'Leave your simple ways, and live. Walk in the way of understanding."'),
  ('e8a957ce-be4d-55ae-a178-04fd3e2b002a', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 7, 7, 'He who corrects a mocker invites insult. He who reproves a wicked man invites abuse.'),
  ('46cacfd8-e02d-52df-ab71-5bc770064b85', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 8, 8, 'Don''t reprove a scoffer, lest he hate you. Reprove a wise man, and he will love you.'),
  ('d22c5f91-2784-5109-aeab-ea1f7e895d5e', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 9, 9, 'Instruct a wise man, and he will be still wiser. Teach a righteous man, and he will increase in learning.'),
  ('6fc04e9d-ef3c-58a1-a6d2-81ece758be3b', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 10, 10, 'The fear of Yahweh is the beginning of wisdom. The knowledge of the Holy One is understanding.'),
  ('dc08115f-0356-5125-a8c5-f509e17750a4', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 11, 11, 'For by me your days will be multiplied. The years of your life will be increased.'),
  ('fc5d9ee7-c943-53c2-a0f5-0aa0cd81046f', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 12, 12, 'If you are wise, you are wise for yourself. If you mock, you alone will bear it.'),
  ('40311604-3d5d-5e4e-a4d1-a07a0ace9d2f', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 13, 13, 'The foolish woman is loud, Undisciplined, and knows nothing.'),
  ('605a8a26-f162-50de-afe6-4c89887bbd37', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 14, 14, 'She sits at the door of her house, on a seat in the high places of the city,'),
  ('a81bb163-2825-59db-a7bb-760d86cb613c', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 15, 15, 'To call to those who pass by, who go straight on their ways,'),
  ('34858571-4896-599e-a13d-037f717c5736', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 16, 16, '"Whoever is simple, let him turn in here." as for him who is void of understanding, she says to him,'),
  ('0500637a-a0bb-5cc4-a2a9-c23fbdafae75', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 17, 17, '"Stolen water is sweet. Food eaten in secret is pleasant."'),
  ('c29b08c9-0c6d-5d08-aa4d-ab85c7367cc5', '88bcfac4-3404-5a0c-a6db-90947a57d0ad', NULL, 18, 18, 'But he doesn''t know that the dead are there, that her guests are in the depths of Sheol.'),
  ('48eba658-0e16-513f-a0eb-b6f0af40ebf6', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 1, 1, 'The proverbs of Solomon. A wise son makes a glad father; but a foolish son brings grief to his mother.'),
  ('89f51685-622a-58a3-a715-7dc4ad3f1955', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 2, 2, 'Treasures of wickedness profit nothing, but righteousness delivers from death.'),
  ('a9bd0947-e7ce-5208-aeab-636b91c9862c', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 3, 3, 'Yahweh will not allow the soul of the righteous to go hungry, but he thrusts away the desire of the wicked.'),
  ('de4cca28-5f61-596f-a0e5-428af4cca33b', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 4, 4, 'He becomes poor who works with a lazy hand, but the hand of the diligent brings wealth.'),
  ('84277737-555f-5ef5-a548-9b6a4befd69e', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 5, 5, 'He who gathers in summer is a wise son, but he who sleeps during the harvest is a son who causes shame.'),
  ('64279839-7485-577d-aca0-61dc92e44a51', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 6, 6, 'Blessings are on the head of the righteous, but violence covers the mouth of the wicked.'),
  ('42596af1-faaf-5870-aefe-c6a3cff753cb', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 7, 7, 'The memory of the righteous is blessed, but the name of the wicked will rot.'),
  ('a8c2b2b9-360d-569b-a8b1-e3cd2412132b', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 8, 8, 'The wise in heart accept commandments, but a chattering fool will fall.'),
  ('556f0305-ea83-5f69-a4fe-1d57a1c13eba', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 9, 9, 'He who walks blamelessly walks surely, but he who perverts his ways will be found out.'),
  ('2a1e86ac-dff2-515f-a791-68ba6e8ace90', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 10, 10, 'One winking with the eye causes sorrow, but a chattering fool will fall.'),
  ('c6f62869-f440-5c53-a861-c67cdaeb834b', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 11, 11, 'The mouth of the righteous is a spring of life, but violence covers the mouth of the wicked.'),
  ('d6471bfb-2c10-5975-aa76-6fa77947b914', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 12, 12, 'Hatred stirs up strife, but love covers all wrongs.'),
  ('5628ec58-7c90-5367-a0ec-baf734f3d029', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 13, 13, 'Wisdom is found on the lips of him who has discernment, but a rod is for the back of him who is void of understanding.'),
  ('b57f003a-c16d-5b92-ae3b-22a5e92fc3ce', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 14, 14, 'Wise men lay up knowledge, but the mouth of the foolish is near ruin.'),
  ('97991065-b953-51da-ae18-e9388e661dd2', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 15, 15, 'The rich man''s wealth is his strong city. The destruction of the poor is their poverty.'),
  ('8fc1f3fe-0363-5f5e-a771-98d527b7d61a', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 16, 16, 'The labor of the righteous leads to life. The increase of the wicked leads to sin.'),
  ('90e9f916-a66f-5104-a6ea-769d0d6d4856', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 17, 17, 'He is in the way of life who heeds correction, but he who forsakes reproof leads others astray.'),
  ('e8e079f5-9360-523a-a41d-7fb1687d3972', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 18, 18, 'He who hides hatred has lying lips. He who utters a slander is a fool.'),
  ('6e0cf65e-f1c4-5b2e-a4e3-7d8ae4018915', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 19, 19, 'In the multitude of words there is no lack of disobedience, but he who restrains his lips does wisely.'),
  ('2c4d99eb-4f62-51d9-a91f-abc9ee1793c8', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 20, 20, 'The tongue of the righteous is like choice silver. The heart of the wicked is of little worth.'),
  ('2629060d-014c-53a2-a6be-e59f12bb0bea', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 21, 21, 'The lips of the righteous feed many, but the foolish die for lack of understanding.'),
  ('921f0c4a-2e3e-58ea-a3ee-46bf50aeaa6e', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 22, 22, 'Yahweh''s blessing brings wealth, and he adds no trouble to it.'),
  ('aba0347e-db1b-5640-a9b5-f0e4f2a6746a', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 23, 23, 'It is a fool''s pleasure to do wickedness, but wisdom is a man of understanding''s pleasure.'),
  ('9e5e1999-4bed-5dd4-a2d5-0767b0fad733', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 24, 24, 'What the wicked fear, will overtake them, but the desire of the righteous will be granted.'),
  ('61e62bcc-fb20-5016-aae6-dc67e640d8ae', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 25, 25, 'When the whirlwind passes, the wicked is no more; but the righteous stand firm forever.'),
  ('8c6aedd4-0fec-5648-a300-288003811ec2', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 26, 26, 'As vinegar to the teeth, and as smoke to the eyes, so is the sluggard to those who send him.'),
  ('b0ad2ff0-6107-5b98-aedd-16b3febb938c', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 27, 27, 'The fear of Yahweh prolongs days, but the years of the wicked shall be shortened.'),
  ('b1ecd68e-e084-5abd-a936-51c0ff77f9fb', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 28, 28, 'The prospect of the righteous is joy, but the hope of the wicked will perish.'),
  ('5b9d8a59-4f6b-56cb-a11d-9deaadd22342', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 29, 29, 'The way of Yahweh is a stronghold to the upright, but it is a destruction to the workers of iniquity.'),
  ('b8592b65-91af-54cc-a842-2b4fdefe7679', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 30, 30, 'The righteous will never be removed, but the wicked will not dwell in the land.'),
  ('48993745-9bf7-5100-a075-271aec9d87e4', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 31, 31, 'The mouth of the righteous brings forth wisdom, but the perverse tongue will be cut off.'),
  ('996ea28d-a56b-57ce-a0c0-b0581c9e2c63', '672d6ae2-1348-58b3-a5fc-c049f5788684', NULL, 32, 32, 'The lips of the righteous know what is acceptable, but the mouth of the wicked is perverse.'),
  ('f952547a-bceb-5785-a254-185c753a4602', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 1, 1, 'A false balance is an abomination to Yahweh, but accurate weights are his delight.'),
  ('a0001f98-4350-50d6-a67a-a38f47f4b91a', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 2, 2, 'When pride comes, then comes shame, but with humility comes wisdom.'),
  ('d449e823-008d-5f1e-ace6-101b907260c4', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 3, 3, 'The integrity of the upright shall guide them, but the perverseness of the treacherous shall destroy them.'),
  ('85f6991d-dedf-5bb0-a25c-0aae16bb1304', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 4, 4, 'Riches don''t profit in the day of wrath, but righteousness delivers from death.'),
  ('8ce33fb1-ebf9-55fe-ad8b-3bc1c8cfdef9', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 5, 5, 'The righteousness of the blameless will direct his way, but the wicked shall fall by his own wickedness.'),
  ('476dd15b-b532-552a-a387-09f1cef49a67', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 6, 6, 'The righteousness of the upright shall deliver them, but the unfaithful will be trapped by evil desires.'),
  ('89f379a1-bff9-5904-a067-f5d039dc1d72', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 7, 7, 'When a wicked man dies, hope perishes, and expectation of power comes to nothing.'),
  ('2b861773-fc94-54a2-ac44-b54aa25e4a8a', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 8, 8, 'A righteous person is delivered out of trouble, and the wicked takes his place.'),
  ('2ae50e79-a689-51d3-afdc-c77edded1acc', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 9, 9, 'With his mouth the godless man destroys his neighbor, but the righteous will be delivered through knowledge.'),
  ('8a80116d-6e67-5e81-ae80-663080aa5e12', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 10, 10, 'When it goes well with the righteous, the city rejoices. When the wicked perish, there is shouting.'),
  ('9a88841b-67d7-54bb-a1e1-19e7c6f7ca4b', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 11, 11, 'By the blessing of the upright, the city is exalted, but it is overthrown by the mouth of the wicked.'),
  ('01c5263a-6a5e-5872-a2ae-3f7fb4595714', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 12, 12, 'One who despises his neighbor is void of wisdom, but a man of understanding holds his peace.'),
  ('693c582f-6d86-5dea-ad8a-1b315e13d242', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 13, 13, 'One who brings gossip betrays a confidence, but one who is of a trustworthy spirit is one who keeps a secret.'),
  ('b99de3a2-b8eb-512c-a9fa-0a4e6ad4946d', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 14, 14, 'Where there is no wise guidance, the nation falls, but in the multitude of counselors there is victory.'),
  ('73074918-3f5f-5c40-a368-28ebff65da3b', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 15, 15, 'He who is collateral for a stranger will suffer for it, but he who refuses pledges of collateral is secure.'),
  ('b0e9e1e6-b8f9-57e0-ad68-d5caaefc9d6e', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 16, 16, 'A gracious woman obtains honor, but violent men obtain riches.'),
  ('be9a0ebf-f9d0-5006-a15b-0004b87af742', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 17, 17, 'The merciful man does good to his own soul, but he who is cruel troubles his own flesh.'),
  ('2358cc07-cf5b-5b69-a3ad-3508f7f82162', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 18, 18, 'Wicked people earn deceitful wages, but one who sows righteousness reaps a sure reward.'),
  ('4efca4ac-9aad-54d0-a8c0-8327b0dd2373', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 19, 19, 'He who is truly righteous gets life. He who pursues evil gets death.'),
  ('34473255-b82f-58fa-acb6-5eb2495aa430', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 20, 20, 'Those who are perverse in heart are an abomination to Yahweh, but those whose ways are blameless are his delight.'),
  ('fa71a23e-4379-5dcd-a5bb-584d57d0d877', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 21, 21, 'Most certainly, the evil man will not be unpunished, but the seed of the righteous will be delivered.'),
  ('1152bf79-279b-52e9-a9de-275ab644caa7', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 22, 22, 'Like a gold ring in a pig''s snout, is a beautiful woman who lacks discretion.'),
  ('c0394353-92fc-520f-a0a9-3e26aaba0981', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 23, 23, 'The desire of the righteous is only good. The expectation of the wicked is wrath.'),
  ('bc207afb-7df3-5f45-a8c7-fae87438af0c', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 24, 24, 'There is one who scatters, and increases yet more. There is one who withholds more than is appropriate, but gains poverty.'),
  ('b23f62de-8c76-515a-a201-a1f02acf9d61', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 25, 25, 'The liberal soul shall be made fat. He who waters shall be watered also himself.'),
  ('89e952d9-ed52-5cab-a7ab-ecc900148a23', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 26, 26, 'People curse someone who withholds grain, but blessing will be on the head of him who sells it.'),
  ('9afa1a51-6090-5ffb-a772-615a57956e0b', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 27, 27, 'He who diligently seeks good seeks favor, but he who searches after evil, it shall come to him.'),
  ('8ddf5bb2-d0aa-547d-a70c-28a86dc3c7ac', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 28, 28, 'He who trusts in his riches will fall, but the righteous shall flourish as the green leaf.'),
  ('f354f142-d3f2-5a04-aeda-1c45ae51afcb', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 29, 29, 'He who troubles his own house shall inherit the wind. The foolish shall be servant to the wise of heart.'),
  ('03d5d72b-5c3b-5412-a906-de466b95b1e0', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 30, 30, 'The fruit of the righteous is a tree of life. He who is wise wins souls.'),
  ('702e6240-8d6e-509e-abd6-709d91d126d5', 'c35a1d0c-d14a-52ee-a45f-d4df18b875ea', NULL, 31, 31, 'Behold, the righteous shall be repaid in the earth; how much more the wicked and the sinner!'),
  ('34341984-fd7c-5c70-a169-b2b3724a55d7', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 1, 1, 'Whoever loves correction loves knowledge, but he who hates reproof is stupid.'),
  ('1040b8a6-ac12-5f12-ab8d-bb344aaa0652', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 2, 2, 'A good man shall obtain favor from Yahweh, but he will condemn a man of wicked devices.'),
  ('223f4d59-aad1-5111-a5d9-cd87847497b4', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 3, 3, 'A man shall not be established by wickedness, but the root of the righteous shall not be moved.'),
  ('112b4c55-66ba-5324-a277-ea33cb45e87f', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 4, 4, 'A worthy woman is the crown of her husband, but a disgraceful wife is as rottenness in his bones.'),
  ('0def5c96-7386-55bb-a561-6679ebfcc765', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 5, 5, 'The thoughts of the righteous are just, but the advice of the wicked is deceitful.'),
  ('9837bdff-fd1b-55a6-a0eb-f6057d8aff42', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 6, 6, 'The words of the wicked are about lying in wait for blood, but the speech of the upright rescues them.'),
  ('61e747b1-f787-543b-a0e6-bf5007ac841f', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 7, 7, 'The wicked are overthrown, and are no more, but the house of the righteous shall stand.'),
  ('1b868f39-b782-5eef-aa90-4d02c51604c1', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 8, 8, 'A man shall be commended according to his wisdom, but he who has a warped mind shall be despised.'),
  ('fa7fde4b-306d-5eba-abf0-813f87435b37', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 9, 9, 'Better is he who is lightly esteemed, and has a servant, than he who honors himself, and lacks bread.'),
  ('f5042b87-177d-5ec2-a59d-9ba186fbe2a2', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 10, 10, 'A righteous man respects the life of his animal, but the tender mercies of the wicked are cruel.'),
  ('d0dd349b-1663-59c6-a755-14612fdb59a5', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 11, 11, 'He who tills his land shall have plenty of bread, but he who chases fantasies is void of understanding.'),
  ('db2f8341-1278-541d-a62c-a6b1eab42008', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 12, 12, 'The wicked desires the plunder of evil men, but the root of the righteous flourishes.'),
  ('d404bd00-6c14-5303-a362-dba6c2c494b8', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 13, 13, 'An evil man is trapped by sinfulness of lips, but the righteous shall come out of trouble.'),
  ('74e11cd7-972c-558d-a37c-d59fcb8428a7', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 14, 14, 'A man shall be satisfied with good by the fruit of his mouth. The work of a man''s hands shall be rewarded to him.'),
  ('57513120-649b-5d94-a8c7-de99f77b1d58', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 15, 15, 'The way of a fool is right in his own eyes, but he who is wise listens to counsel.'),
  ('5d36d6c2-3930-58eb-a903-337df3cc15ef', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 16, 16, 'A fool shows his annoyance the same day, but one who overlooks an insult is prudent.'),
  ('a59e801b-a0da-5067-ae72-96ef6b6fb7aa', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 17, 17, 'He who is truthful testifies honestly, but a false witness lies.'),
  ('65f5190f-9409-56b6-a655-736de817b9db', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 18, 18, 'There is one who speaks rashly like the piercing of a sword, but the tongue of the wise heals.'),
  ('90a4087d-9d64-5dd3-abf5-f28bb9bd9be2', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 19, 19, 'Truth''s lips will be established forever, but a lying tongue is only momentary.'),
  ('705b4a26-e0bd-5d8b-a1fa-4330535d414b', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 20, 20, 'Deceit is in the heart of those who plot evil, but joy comes to the promoters of peace.'),
  ('8b31d05d-b0bb-5a68-a064-1d98bb9b3fb9', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 21, 21, 'No mischief shall happen to the righteous, but the wicked shall be filled with evil.'),
  ('5d214bda-5036-5c0f-aee2-fb7c7d4fd5c4', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 22, 22, 'Lying lips are an abomination to Yahweh, but those who do the truth are his delight.'),
  ('3d21a39c-f8f1-58f9-a095-b84d4669e3d7', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 23, 23, 'A prudent man keeps his knowledge, but the hearts of fools proclaim foolishness.'),
  ('1d867777-cb0f-59d7-a2cd-42c0f42cf9c8', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 24, 24, 'The hands of the diligent ones shall rule, but laziness ends in slave labor.'),
  ('2d7e331c-40f0-5227-a573-af5b372e5520', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 25, 25, 'Anxiety in a man''s heart weighs it down, but a kind word makes it glad.'),
  ('f5553b1d-d77b-5f96-a605-03282b2421e7', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 26, 26, 'A righteous person is cautious in friendship, but the way of the wicked leads them astray.'),
  ('8b5ec576-e06e-5a51-aaae-72a92cbb92da', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 27, 27, 'The slothful man doesn''t roast his game, but the possessions of diligent men are prized.'),
  ('93cc5f0e-a4da-5c5c-a8ed-1ac669c070e5', 'eff63871-9e06-572c-a9a1-086f25fa2b6f', NULL, 28, 28, 'In the way of righteousness is life; in its path there is no death.'),
  ('f37b63c0-22f3-5df8-aff2-66ea48e3e708', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 1, 1, 'A wise son listens to his father''s instruction, but a scoffer doesn''t listen to rebuke.'),
  ('d5278a10-090f-5d33-a1f8-ac55c9df908f', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 2, 2, 'By the fruit of his lips, a man enjoys good things; but the unfaithful crave violence.'),
  ('77d25452-f378-5117-ad23-4264a752633a', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 3, 3, 'He who guards his mouth guards his soul. One who opens wide his lips comes to ruin.'),
  ('962b6782-662c-51ea-ad40-64508f8f1df3', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 4, 4, 'The soul of the sluggard desires, and has nothing, but the desire of the diligent shall be fully satisfied.'),
  ('8a5dca45-1de1-5cd0-a942-7cda3eda8347', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 5, 5, 'A righteous man hates lies, but a wicked man brings shame and disgrace.'),
  ('932959b3-d50f-553d-acac-f0799bcc23e4', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 6, 6, 'Righteousness guards the way of integrity, but wickedness overthrows the sinner.'),
  ('cd694f96-fca3-5409-a10e-657b90b30a51', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 7, 7, 'There are some who pretend to be rich, yet have nothing. There are some who pretend to be poor, yet have great wealth.'),
  ('b0dbe0b8-45af-5d20-a5a0-787f5f227260', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 8, 8, 'The ransom of a man''s life is his riches, but the poor hear no threats.'),
  ('4326aad5-18a5-5d83-a2d2-30b2afcde0f6', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 9, 9, 'The light of the righteous shines brightly, but the lamp of the wicked is snuffed out.'),
  ('cd54a2e8-6dcc-536b-ad11-15188eb6ce1b', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 10, 10, 'Pride only breeds quarrels, but with ones who take advice is wisdom.'),
  ('22590724-52df-514b-a894-30519dd8fcfe', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 11, 11, 'Wealth gained dishonestly dwindles away, but he who gathers by hand makes it grow.'),
  ('fe03abbd-3a0c-5a53-a3b8-d6b14e8b4538', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 12, 12, 'Hope deferred makes the heart sick, but when longing is fulfilled, it is a tree of life.'),
  ('3771ea9f-6dcb-5c17-ae4a-b4ef596a016f', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 13, 13, 'Whoever despises instruction will pay for it, but he who respects a command will be rewarded.'),
  ('3bf134b5-b5e1-50d9-a4f8-b7314643331f', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 14, 14, 'The teaching of the wise is a spring of life, to turn from the snares of death.'),
  ('d9689b7b-6123-54a8-a5ed-71c48cbeb188', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 15, 15, 'Good understanding wins favor; but the way of the unfaithful is hard.'),
  ('a8933621-2498-5ce9-a9d7-11d999b6715c', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 16, 16, 'Every prudent man acts from knowledge, but a fool exposes folly.'),
  ('e0a52def-cb87-5d5d-ac0e-1b32684b1f86', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 17, 17, 'A wicked messenger falls into trouble, but a trustworthy envoy gains healing.'),
  ('0e742afd-b660-560e-a7d4-d6db5061eb12', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 18, 18, 'Poverty and shame come to him who refuses discipline, but he who heeds correction shall be honored.'),
  ('544e8503-2671-550c-a284-9230b0cbb6cf', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 19, 19, 'Longing fulfilled is sweet to the soul, but fools detest turning from evil.'),
  ('421e695a-66ee-5162-ab0c-3e78cd2a2dfd', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 20, 20, 'One who walks with wise men grows wise, but a companion of fools suffers harm.'),
  ('95df8814-40e3-5ec2-a4bf-e634cd752455', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 21, 21, 'Misfortune pursues sinners, but prosperity rewards the righteous.'),
  ('5b35fb8b-caf7-5e75-a66e-b0daac4e9108', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 22, 22, 'A good man leaves an inheritance to his children''s children, but the wealth of the sinner is stored for the righteous.'),
  ('f8ec428c-a004-579a-a674-3a04fa5f5a7b', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 23, 23, 'An abundance of food is in poor people''s fields, but injustice sweeps it away.'),
  ('3b8928b9-c1ef-5cd7-ab5f-c69ccff534ad', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 24, 24, 'One who spares the rod hates his son, but one who loves him is careful to discipline him.'),
  ('a7daa63f-b8ee-559e-a1a3-5d8b7aeba7e3', '62445abe-c0c7-5a64-a06f-8953de9ca4bd', NULL, 25, 25, 'The righteous one eats to the satisfying of his soul, but the belly of the wicked goes hungry.'),
  ('a4371ab5-a7bf-5b44-a205-f168e1c682ff', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 1, 1, 'Every wise woman builds her house, but the foolish one tears it down with her own hands.'),
  ('e77cb34b-1621-5c14-a65b-04e1c51e2d15', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 2, 2, 'He who walks in his uprightness fears Yahweh, but he who is perverse in his ways despises him.'),
  ('46328a3d-004a-588c-aade-fc4e0d3e4f50', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 3, 3, 'The fool''s talk brings a rod to his back, but the lips of the wise protect them.'),
  ('2ceae9dd-b261-5034-adf8-4d3d4198f4ea', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 4, 4, 'Where no oxen are, the crib is clean, but much increase is by the strength of the ox.'),
  ('2f3f5609-228c-56ce-ad11-ab302b8eb17a', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 5, 5, 'A truthful witness will not lie, but a false witness pours out lies.'),
  ('5f8530b6-4025-51c5-a1e5-2dd1fe8b8d9f', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 6, 6, 'A scoffer seeks wisdom, and doesn''t find it, but knowledge comes easily to a discerning person.'),
  ('123fbfc9-21f6-597d-a5fd-6153c6b13f5e', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 7, 7, 'Stay away from a foolish man, for you won''t find knowledge on his lips.'),
  ('c94d4fe4-8c86-5662-aede-0aa918dc2be9', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 8, 8, 'The wisdom of the prudent is to think about his way, but the folly of fools is deceit.'),
  ('1d28473d-89c9-5da6-ac90-02cc5bd56203', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 9, 9, 'Fools mock at making atonement for sins, but among the upright there is good will.'),
  ('a0ade1fb-2faa-539f-a8d4-d1a1014e2c54', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 10, 10, 'The heart knows its own bitterness and joy; he will not share these with a stranger.'),
  ('77573a87-e17b-58d7-a5a2-ad0dbb4249e7', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 11, 11, 'The house of the wicked will be overthrown, but the tent of the upright will flourish.'),
  ('e809d7dd-dd4c-535f-a163-eb766069966c', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 12, 12, 'There is a way which seems right to a man, but in the end it leads to death.'),
  ('235e5576-4c28-5509-a534-b0650ebef6de', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 13, 13, 'Even in laughter the heart may be sorrowful, and mirth may end in heaviness.'),
  ('66abf77e-354e-5e73-a481-964f012c85e5', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 14, 14, 'The unfaithful will be repaid for his own ways; likewise a good man will be rewarded for his ways.'),
  ('bcf829f3-2fcf-5e12-a2de-cdbf3080ee0a', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 15, 15, 'A simple man believes everything, but the prudent man carefully considers his ways.'),
  ('5bd4e0f1-7e6b-5111-a1ca-27dcbc2b1f31', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 16, 16, 'A wise man fears, and shuns evil, but the fool is hotheaded and reckless.'),
  ('603e8ac7-0ae0-5112-ac4c-2bf4be24cacd', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 17, 17, 'He who is quick to become angry will commit folly, and a crafty man is hated.'),
  ('809a53d3-2883-5e40-af18-ac0f1c060a0a', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 18, 18, 'The simple inherit folly, but the prudent are crowned with knowledge.'),
  ('648e4c0a-45d3-5009-a3d0-edef17e11669', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 19, 19, 'The evil bow down before the good, and the wicked at the gates of the righteous.'),
  ('9e567cc6-7f09-5c20-aba2-1345f92c296a', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 20, 20, 'The poor person is shunned even by his own neighbor, but the rich person has many friends.'),
  ('e683d8b4-2287-5081-a44d-473f6e74a456', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 21, 21, 'He who despises his neighbor sins, but blessed is he who has pity on the poor.'),
  ('784bb910-b049-5e4b-a3b1-1637ae206e90', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 22, 22, 'Don''t they go astray who plot evil? But love and faithfulness belong to those who plan good.'),
  ('28852d63-b2ed-5ff3-a5c9-87132dfbafb4', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 23, 23, 'In all hard work there is profit, but the talk of the lips leads only to poverty.'),
  ('d0e4effd-2b2d-52f3-a3cb-de3eaa0edce3', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 24, 24, 'The crown of the wise is their riches, but the folly of fools crowns them with folly.'),
  ('892350ce-1d31-5b8f-ae3d-3f096750581b', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 25, 25, 'A truthful witness saves souls, but a false witness is deceitful.'),
  ('60b40f1a-4c0c-5359-abcf-2e7a76c0d14e', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 26, 26, 'In the fear of Yahweh is a secure fortress, and he will be a refuge for his children.'),
  ('5c8c9496-008b-5475-af9e-8111f40284ea', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 27, 27, 'The fear of Yahweh is a fountain of life, turning people from the snares of death.'),
  ('a965052c-7f90-5228-a44a-0daa18a8b5e5', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 28, 28, 'In the multitude of people is the king''s glory, but in the lack of people is the destruction of the prince.'),
  ('d0071d42-62eb-5b52-a057-06d8382a4eb1', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 29, 29, 'He who is slow to anger has great understanding, but he who has a quick temper displays folly.'),
  ('ec68817c-0ba6-5a1e-a55d-5481c93ec977', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 30, 30, 'The life of the body is a heart at peace, but envy rots the bones.'),
  ('731b4c57-35bc-57d6-a6bf-9bec6e4fa11f', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 31, 31, 'He who oppresses the poor shows contempt for his Maker, but he who is kind to the needy honors him.'),
  ('c0f1b1f7-b0bc-50d7-adb3-fe251bf0bfdf', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 32, 32, 'The wicked is brought down in his calamity, but in death, the righteous has a refuge.'),
  ('f4ad88c6-08b3-59ff-a8e3-040f3fded29e', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 33, 33, 'Wisdom rests in the heart of one who has understanding, and is even made known in the inward part of fools.'),
  ('a7c838b3-9fc6-5f18-ad50-1b13c1c324f2', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 34, 34, 'Righteousness exalts a nation, but sin is a disgrace to any people.'),
  ('57e42e63-f0f9-56cc-a9ca-ce1b8e0c7a07', '0ebcddd7-71dd-52dd-a6db-4516d112db6d', NULL, 35, 35, 'The king''s favor is toward a servant who deals wisely, but his wrath is toward one who causes shame.'),
  ('21048d4e-6af8-5014-ac7a-98adbf5a9a21', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 1, 1, 'A gentle answer turns away wrath, but a harsh word stirs up anger.'),
  ('ca456aeb-9147-5466-a8e7-818e6a9b89b4', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 2, 2, 'The tongue of the wise commends knowledge, but the mouth of fools gush out folly.'),
  ('f7f46869-e715-5f9e-a7f2-e223243e3648', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 3, 3, 'Yahweh''s eyes are everywhere, keeping watch on the evil and the good.'),
  ('820cf868-a862-541f-a47f-073bd639fb68', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 4, 4, 'A gentle tongue is a tree of life, but deceit in it crushes the spirit.'),
  ('d6c15bd6-d0fa-54e0-a28d-e6f47f52f71e', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 5, 5, 'A fool despises his father''s correction, but he who heeds reproof shows prudence.'),
  ('5b2f8546-3e02-5b69-aecd-7655fa44df58', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 6, 6, 'In the house of the righteous is much treasure, but the income of the wicked brings trouble.'),
  ('c4eb675a-81ca-567a-a9c0-519ad74c35d8', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 7, 7, 'The lips of the wise spread knowledge; not so with the heart of fools.'),
  ('2da1662f-0861-556e-a5eb-f6f91e383f70', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 8, 8, 'The sacrifice made by the wicked is an abomination to Yahweh, but the prayer of the upright is his delight.'),
  ('f72c7c94-8e51-541f-a949-d15f00e83ade', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 9, 9, 'The way of the wicked is an abomination to Yahweh, but he loves him who follows after righteousness.'),
  ('58eaf945-8399-50de-ae55-1da074469f75', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 10, 10, 'There is stern discipline for one who forsakes the way: whoever hates reproof shall die.'),
  ('145d50a1-437e-5754-a65f-45a288588d14', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 11, 11, 'Sheol and Abaddon are before Yahweh-- how much more then the hearts of the children of men!'),
  ('4e4eb426-b29a-5467-a052-073d43d80bda', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 12, 12, 'A scoffer doesn''t love to be reproved; he will not go to the wise.'),
  ('e54c5866-3d25-5a53-a366-3b6d90c5fc2e', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 13, 13, 'A glad heart makes a cheerful face; but an aching heart breaks the spirit.'),
  ('bc1fe84a-6d9f-5486-a74f-482eb769032d', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 14, 14, 'The heart of one who has understanding seeks knowledge, but the mouths of fools feed on folly.'),
  ('d52c0c1f-0d86-5c59-a8e3-9d5e3dc0688f', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 15, 15, 'All the days of the afflicted are wretched, but one who has a cheerful heart enjoys a continual feast.'),
  ('0cbe9659-7fa7-5f50-ab3b-9b26a4e45541', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 16, 16, 'Better is little, with the fear of Yahweh, than great treasure with trouble.'),
  ('ca38f8b2-286f-5f00-ab1d-faef12454d36', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 17, 17, 'Better is a dinner of herbs, where love is, than a fattened calf with hatred.'),
  ('37224d5e-716f-5a2e-a037-d6c43f4ef64f', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 18, 18, 'A wrathful man stirs up contention, but one who is slow to anger appeases strife.'),
  ('8fd842e8-97a8-5e0e-a771-e13ab7b193cb', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 19, 19, 'The way of the sluggard is like a thorn patch, but the path of the upright is a highway.'),
  ('dfa75b1b-5c59-5a2c-aff2-1c0f6ea85286', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 20, 20, 'A wise son makes a father glad, but a foolish man despises his mother.'),
  ('4bf4dbfc-b935-5f0c-ab05-eb77ea2628a8', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 21, 21, 'Folly is joy to one who is void of wisdom, but a man of understanding keeps his way straight.'),
  ('c1f20899-8ab6-5d83-aa66-38b06baf14cc', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 22, 22, 'Where there is no counsel, plans fail; but in a multitude of counselors they are established.'),
  ('c8793e62-58ad-582b-a66c-a6ff4c9b5264', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 23, 23, 'Joy comes to a man with the reply of his mouth. How good is a word at the right time!'),
  ('ed7b7688-6439-5f4d-a297-c93426932c17', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 24, 24, 'The path of life leads upward for the wise, to keep him from going downward to Sheol.'),
  ('dec84f5f-578f-5602-a3f1-ae42f2ed448a', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 25, 25, 'Yahweh will uproot the house of the proud, but he will keep the widow''s borders intact.'),
  ('5d62b3f6-b269-5efa-aa7c-5b3856c0b7c3', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 26, 26, 'Yahweh detests the thoughts of the wicked, but the thoughts of the pure are pleasing.'),
  ('7d59e7f8-26ed-598c-acd7-29c31b47ae44', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 27, 27, 'He who is greedy for gain troubles his own house, but he who hates bribes will live.'),
  ('621e6428-ef4e-5c9b-a782-6aa2002648b8', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 28, 28, 'The heart of the righteous weighs answers, but the mouth of the wicked gushes out evil.'),
  ('03769802-81cf-5f36-a6ea-069d3f418bec', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 29, 29, 'Yahweh is far from the wicked, but he hears the prayer of the righteous.'),
  ('c629c590-6f2e-50c4-a5f5-c50a97448e84', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 30, 30, 'The light of the eyes rejoices the heart. Good news gives health to the bones.'),
  ('2bec8207-46f5-5a87-ae0f-a7cd015eb3f3', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 31, 31, 'The ear that listens to reproof lives, and will be at home among the wise.'),
  ('66105489-fb32-5e79-a63b-7c8bedabbb48', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 32, 32, 'He who refuses correction despises his own soul, but he who listens to reproof gets understanding.'),
  ('b9feeeef-5cba-5456-a701-0f4c04d1d130', '8e709544-c1cf-51be-a4ba-7101571b94f0', NULL, 33, 33, 'The fear of Yahweh teaches wisdom. Before honor is humility.'),
  ('a4897d0a-4678-539c-a060-2c2da819ae98', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 1, 1, 'The plans of the heart belong to man, but the answer of the tongue is from Yahweh.'),
  ('ad2767af-505d-5d17-ac7f-6ca70c5e790a', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 2, 2, 'All the ways of a man are clean in his own eyes; but Yahweh weighs the motives.'),
  ('3b1caa46-7a7a-5656-ada2-bbf61e8da809', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 3, 3, 'Commit your deeds to Yahweh, and your plans shall succeed.'),
  ('7d0ec73a-9292-5c90-ab71-119821144e78', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 4, 4, 'Yahweh has made everything for its own end-- yes, even the wicked for the day of evil.'),
  ('db92be15-5eec-5058-a91c-abda5ccf827b', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 5, 5, 'Everyone who is proud in heart is an abomination to Yahweh: they shall certainly not be unpunished.'),
  ('fd79a171-abe4-59fc-ac34-7e39a3e7e892', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 6, 6, 'By mercy and truth iniquity is atoned for. By the fear of Yahweh men depart from evil.'),
  ('eef7e49f-fb2e-515f-ab2a-1278db80c8a3', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 7, 7, 'When a man''s ways please Yahweh, he makes even his enemies to be at peace with him.'),
  ('96ce4713-7960-5e7a-a22d-409185e0de6a', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 8, 8, 'Better is a little with righteousness, than great revenues with injustice.'),
  ('246b661e-b724-515b-a82f-3e766ba1097b', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 9, 9, 'A man''s heart plans his course, but Yahweh directs his steps.'),
  ('ed84e7ac-3602-5a3d-ac08-d14e43b3c4bc', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 10, 10, 'Inspired judgments are on the lips of the king. He shall not betray his mouth.'),
  ('3a5ddbb6-5c7a-5e91-ab8e-3a69644be7fc', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 11, 11, 'Honest balances and scales are Yahweh''s; all the weights in the bag are his work.'),
  ('6386ca6d-d83b-5c24-a57f-3e6cc95a1620', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 12, 12, 'It is an abomination for kings to do wrong, for the throne is established by righteousness.'),
  ('1bc2fb74-f0f1-5a88-a63f-9771e3829395', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 13, 13, 'Righteous lips are the delight of kings. They value one who speaks the truth.'),
  ('3be30f2e-a9ab-5560-a2c6-ed77c094528c', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 14, 14, 'The king''s wrath is a messenger of death, but a wise man will pacify it.'),
  ('59c30f54-733b-5cf0-a98b-22b89ead2164', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 15, 15, 'In the light of the king''s face is life. His favor is like a cloud of the spring rain.'),
  ('6a8a2ad6-e919-5db0-a4e3-2d84d2c2e595', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 16, 16, 'How much better it is to get wisdom than gold! Yes, to get understanding is to be chosen rather than silver.'),
  ('20dbf959-b8e8-5542-a5c0-9cadcdcb263f', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 17, 17, 'The highway of the upright is to depart from evil. He who keeps his way preserves his soul.'),
  ('2be0bd79-afe2-5ae8-a6fa-7761c1089107', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 18, 18, 'Pride goes before destruction, and a haughty spirit before a fall.'),
  ('63c9ba30-f4a7-5e2c-a3f7-de5dff90a415', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 19, 19, 'It is better to be of a lowly spirit with the poor, than to divide the plunder with the proud.'),
  ('876a2906-5627-51f0-aa0d-4755197ee647', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 20, 20, 'He who heeds the Word finds prosperity. Whoever trusts in Yahweh is blessed.')
